/* ═══════════════════════════════════════════════════════════════════
   dotes.js — Dotes D&D 5e / 5.5e
   Fuentes: PHB 2024 (origen, generales, estilos de lucha, dones épicos) ·
            PHB 2014 · Xanathar's (XGtE) · Tasha's (TCE) · Fizban's (FTD) ·
            Strixhaven (SCC) · y, contrastadas con 5etools, HoF 2024 · EFotA 2024 ·
            ABH 2024 · THW 2024 · LFL 2024 · BGotG · SotDQ · SatO · ERftLW · BMT · MTF ·
            PSK · PSX (cada dote lleva su fuente en la clave)
   Nombres en inglés · Descripciones en español.
   Las dotes que existen en 2014 y 2024 con efectos casi idénticos van en una
   sola entrada "[PHB 2024 / TCE]"; las que cambiaron mucho se separan en
   "[PHB 2024]" y "[PHB 2014]".
   Campos: n (nombre), tipo (grupo del desplegable), d (texto),
     a  = cómo se usa en combate (lo lee el panel de Acciones):
          "A" Acción · "B" Acción Adicional · "R" Reacción · "O" otro/sin acción
          (combinable: "BR"). Sin a = dote pasiva.
     alias = nombres antiguos de la dote: las fichas guardadas con ellos
          siguen reconociéndose.
═══════════════════════════════════════════════════════════════════ */

const DND_DOTES = [

  /* ════════════════════════════════
     DOTES DE ORIGEN (PHB 2024) — se obtienen con el trasfondo (Nv.1) o más tarde como dote general
  ════════════════════════════════ */
  { n:"Alert [PHB 2024]", tipo:"Origen", a:"O", alias:["Alert [PHB'24]"], d:"Competencia en iniciativa: sumas tu bonificador de competencia a las tiradas de iniciativa. Intercambio de iniciativa: justo después de tirar iniciativa puedes intercambiar tu resultado con el de un aliado voluntario del mismo combate (ninguno de los dos puede estar Incapacitado)." },
  { n:"Crafter [PHB 2024]", tipo:"Origen", alias:["Crafter [PHB'24]"], d:"Competencia con 3 Herramientas de Artesano distintas entre sí, a tu elección, de la tabla de Fabricación Rápida. Descuento: 20 % al comprar objetos no mágicos. Fabricación Rápida: al terminar un Descanso Largo, si tienes las herramientas y la competencia, creas 1 objeto de equipo de la tabla; dura hasta tu siguiente Descanso Largo. Tabla de Fabricación Rápida (herramienta: objetos): Carpintero: Ladder, Torch; Peletero: Crossbow Bolt Case, Map or Scroll Case, Pouch; Albañil: Block and Tackle; Alfarero: Jug, Lamp; Herrero: Ball Bearings, Bucket, Caltrops, Grappling Hook, Iron Pot; Hojalatero: Bell, Shovel, Tinderbox; Tejedor: Basket, Rope, Net, Tent; Tallista: Club, Greatclub, Quarterstaff." },
  { n:"Healer [PHB 2024]", tipo:"Origen", a:"A", alias:["Healer [PHB'24]"], d:"Médico de Batalla: con un Botiquín de Sanador, gastas 1 uso y realizas la acción Utilizar sobre una criatura a 5 pies: esa criatura gasta 1 Dado de Golpe, tú lo tiras y recupera PG iguales al resultado + tu bonificador de competencia. Repetir curación: al tirar dados para restaurar PG con esta dote o con un conjuro, puedes repetir cada 1 y usar la nueva tirada." },
  { n:"Lucky [PHB 2024]", tipo:"Origen", a:"O", alias:["Lucky [PHB'24]"], d:"Puntos de Suerte = tu bonificador de competencia (los recuperas todos con un Descanso Largo). Ventaja: al hacer una Prueba de d20, gastas 1 punto para tener Ventaja. Desventaja: cuando una criatura te hace una tirada de ataque, gastas 1 punto para imponerle Desventaja." },
  { n:"Magic Initiate [PHB 2024]", tipo:"Origen", alias:["Magic Initiate [PHB'24]"], d:"Eliges la lista de Clérigo, Druida o Mago. Aprendes 2 trucos y 1 conjuro de nivel 1 de esa lista; el de nivel 1 siempre está preparado y puedes lanzarlo 1 vez sin espacio por Descanso Largo (o con espacios). Característica de lanzamiento: INT, SAB o CAR. Al subir de nivel puedes cambiar un conjuro de la dote por otro del mismo nivel de la lista. Repetible con listas distintas." },
  { n:"Musician [PHB 2024]", tipo:"Origen", a:"O", alias:["Musician [PHB'24]"], d:"Competencia con 3 Instrumentos Musicales. Canción Alentadora: al terminar un Descanso Corto o Largo puedes tocar un instrumento con el que seas competente y dar Inspiración Heroica a tantos aliados que te oigan como tu bonificador de competencia." },
  { n:"Savage Attacker [PHB 2024]", tipo:"Origen", alias:["Savage Attacker [PHB'14 / PHB'24]"], d:"Una vez por turno, al impactar con un arma, tiras los dados de daño del arma dos veces y usas el resultado que prefieras. [2014: sólo ataques cuerpo a cuerpo y se volvía a tirar el daño.]" },
  { n:"Skilled [PHB 2024]", tipo:"Origen", alias:["Skilled [PHB'14 / PHB'24]"], d:"Ganas competencia en 3 habilidades o herramientas a tu elección. Repetible. [2014: mismo efecto; no repetible.]" },
  { n:"Tavern Brawler [PHB 2024]", tipo:"Origen", alias:["Tavern Brawler [PHB'24]"], d:"Golpe Desarmado mejorado: tu Golpe Desarmado puede infligir daño contundente igual a 1d4 + mod. FUE en lugar del daño normal. Repetir daño: si sacas 1 en un dado de daño de tu Golpe Desarmado, repites ese dado y usas el nuevo resultado. Empujón: una vez por turno, al impactar con un Golpe Desarmado como parte de la acción Atacar, además del daño empujas al objetivo 5 pies. Competencia con armas improvisadas." },
  { n:"Tough [PHB 2024]", tipo:"Origen", alias:["Tough [PHB'14 / PHB'24]"], d:"Tus PG máximos aumentan en el doble de tu nivel al obtener la dote y en 2 más cada vez que subes de nivel. [2014: dote general con el mismo efecto.]" },

  /* ════════════════════════════════
     DOTES GENERALES (PHB 2024) — requieren nivel 4+
  ════════════════════════════════ */
  { n:"Ability Score Improvement [PHB 2024]", tipo:"General", alias:["Ability Score Improvement [PHB'14 / PHB'24]"], d:"Req. Nv.4+. Aumentas una característica en 2, o dos características en 1 cada una (máx. 20). Repetible. [2014: era una opción de la clase, no una dote.]" },
  { n:"Actor [PHB 2024]", tipo:"General", alias:["Actor [PHB'24]"], d:"Req. Nv.4+, CAR 13+. +1 CAR (máx. 20). Imitación: mientras estás disfrazado como una persona real o ficticia, tienes Ventaja en las pruebas de CAR (Engaño o Interpretación) para convencer a otros de que eres esa persona. Mimetismo: puedes copiar sonidos y voces de criaturas; quien los oiga hace una prueba de SAB (Perspicacia) CD 8 + mod. CAR + comp. para detectar la imitación." },
  { n:"Athlete [PHB 2024]", tipo:"General", alias:["Athlete [PHB'24]"], d:"Req. Nv.4+, FUE o DES 13+. +1 FUE o DES (máx. 20). Velocidad de trepar igual a tu Velocidad. Levantarte estando Tumbado sólo cuesta 5 pies de movimiento. Saltos de longitud o altura con sólo 5 pies de carrerilla." },
  { n:"Charger [PHB 2024]", tipo:"General", alias:["Charger [PHB'24]"], d:"Req. Nv.4+, FUE o DES 13+. +1 FUE o DES (máx. 20). Al realizar la acción Correr, tu Velocidad aumenta 10 pies durante esa acción. Ataque en carga: si te mueves al menos 10 pies en línea recta hacia un objetivo justo antes de impactarlo con un ataque cuerpo a cuerpo durante la acción Atacar, una vez por turno infliges +1d8 de daño o lo empujas hasta 10 pies (si es como mucho un tamaño mayor que tú)." },
  { n:"Chef [PHB 2024 / TCE]", tipo:"General", a:"B", alias:["Chef [TCE / PHB'24]"], d:"Req. Nv.4+ (PHB 2024). +1 CON o SAB (máx. 20). Competencia con Utensilios de Cocinero. Comida reconstituyente: durante un Descanso Corto puedes cocinar, si tienes ingredientes y Utensilios de Cocinero a mano, comida para hasta 4 + comp. criaturas; quienes la coman y gasten Dados de Golpe al final del descanso recuperan 1d8 PG extra. Golosinas: con 1 hora de trabajo o al terminar un Descanso Largo, si tienes ingredientes y Utensilios de Cocinero a mano, preparas tantas golosinas como tu bonificador de competencia; duran 8 horas; comerse una es una Acción Adicional y da PG temporales iguales a tu bonificador de competencia. [TCE 2014: mismo efecto, sin requisito de nivel.]" },
  { n:"Crossbow Expert [PHB 2024]", tipo:"General", alias:["Crossbow Expert [PHB'24]"], d:"Req. Nv.4+, DES 13+. +1 DES (máx. 20). Ignoras la propiedad Carga de las ballestas de mano, ligera y pesada. Si empuñas una de ellas, puedes cargarle munición aunque no tengas una mano libre. Disparar en cuerpo a cuerpo: no sufres Desventaja al atacar a distancia con ballesta a 5 pies de un enemigo. Doble arma: al hacer el ataque adicional de la propiedad Ligera con una ballesta que la tenga, añades tu modificador de característica a su daño." },
  { n:"Crusher [PHB 2024 / TCE]", tipo:"General", alias:["Crusher [PHB'24]","Crusher [TCE]"], d:"Req. Nv.4+ (PHB 2024). +1 FUE o CON (máx. 20). Empujón: una vez por turno, al impactar con un ataque que inflige daño contundente, mueves al objetivo 5 pies a un espacio libre (si es como mucho un tamaño mayor que tú). Crítico: al causar un crítico con daño contundente, las tiradas de ataque contra esa criatura tienen Ventaja hasta el inicio de tu siguiente turno." },
  { n:"Defensive Duelist [PHB 2024]", tipo:"General", a:"R", alias:["Defensive Duelist [PHB'24]"], d:"Req. Nv.4+, DES 13+. +1 DES (máx. 20). Parada: si empuñas un arma de Finura y una criatura te impacta con un ataque cuerpo a cuerpo, puedes usar tu Reacción para sumar tu bonificador de competencia a tu CA, pudiendo hacer que el ataque falle. Mantienes ese bonificador a la CA contra ataques cuerpo a cuerpo hasta el inicio de tu siguiente turno." },
  { n:"Dual Wielder [PHB 2024]", tipo:"General", a:"B", alias:["Dual Wielder [PHB'24]"], d:"Req. Nv.4+, FUE o DES 13+. +1 FUE o DES (máx. 20). Combate con dos armas mejorado: si atacas con un arma Ligera durante la acción Atacar, puedes hacer un ataque extra con Acción Adicional con un arma cuerpo a cuerpo distinta que no tenga A Dos Manos (no añades tu modificador al daño, salvo que sea negativo). Desenfundado rápido: sacas o guardas dos armas sin A Dos Manos en lugar de una." },
  { n:"Durable [PHB 2024]", tipo:"General", a:"B", alias:["Durable [PHB'24]"], d:"Req. Nv.4+. +1 CON (máx. 20). Burlar a la Muerte: Ventaja en salvaciones de muerte. Recuperación Rápida: como Acción Adicional gastas 1 Dado de Golpe, lo tiras y recuperas PG iguales al resultado." },
  { n:"Elemental Adept [PHB 2024]", tipo:"General", alias:["Elemental Adept [PHB'24]"], d:"Req. Nv.4+, rasgo Lanzamiento de Conjuros o Magia de Pacto. +1 INT, SAB o CAR (máx. 20). Maestría Elemental: eliges Ácido, Frío, Fuego, Relámpago o Trueno; tus conjuros ignoran la Resistencia a ese tipo y, al tirar su daño, puedes tratar cada 1 como 2. Repetible con tipos distintos. [2014: sin ASI.]" },
  { n:"Fey-Touched [PHB 2024 / TCE]", tipo:"General", a:"B", alias:["Fey Touched [TCE / PHB'24]"], d:"Req. Nv.4+ (PHB 2024). +1 INT, SAB o CAR (máx. 20). Magia Feérica: aprendes Misty Step y 1 conjuro de nivel 1 de Adivinación o Encantamiento a tu elección; siempre preparados; puedes lanzar cada uno 1 vez por Descanso Largo sin espacio (o con espacios). Característica de lanzamiento: la que aumentaste. [TCE 2014: igual, sin requisito de nivel.]" },
  { n:"Grappler [PHB 2024]", tipo:"General", alias:["Grappler [PHB'24]"], d:"Req. Nv.4+, FUE o DES 13+. +1 FUE o DES (máx. 20). Golpear y agarrar: al impactar con un Golpe Desarmado durante la acción Atacar, puedes aplicar a la vez el daño y el agarre (una vez por turno). Ventaja de ataque: Ventaja en ataques contra una criatura que tengas agarrada. Luchador veloz: mover a una criatura agarrada de tu tamaño o menor no te cuesta movimiento adicional." },
  { n:"Great Weapon Master [PHB 2024]", tipo:"General", a:"B", alias:["Great Weapon Master [PHB'24]"], d:"Req. Nv.4+, FUE 13+. +1 FUE (máx. 20). Maestría con Armas Pesadas: al impactar con un arma Pesada durante la acción Atacar en tu turno, infliges daño extra igual a tu bonificador de competencia. Hender: justo después de causar un crítico o reducir a 0 PG a una criatura con un arma cuerpo a cuerpo, puedes hacer un ataque con esa misma arma como Acción Adicional. [2014: –5 al ataque para +10 al daño con armas Pesadas.]" },
  { n:"Heavily Armored [PHB 2024]", tipo:"General", alias:["Heavily Armored [PHB'24]"], d:"Req. Nv.4+, Entrenamiento con Armadura Media. +1 FUE o CON (máx. 20). Entrenamiento con Armadura Pesada." },
  { n:"Heavy Armor Master [PHB 2024]", tipo:"General", alias:["Heavy Armor Master [PHB'24]"], d:"Req. Nv.4+, Entrenamiento con Armadura Pesada. +1 FUE o CON (máx. 20). Reducción de daño: mientras llevas armadura pesada, el daño contundente, perforante y cortante que sufres de un ataque se reduce en tu bonificador de competencia." },
  { n:"Inspiring Leader [PHB 2024]", tipo:"General", a:"O", alias:["Inspiring Leader [PHB'24]"], d:"Req. Nv.4+, SAB o CAR 13+. +1 SAB o CAR (máx. 20). Actuación Estimulante: al terminar un Descanso Corto o Largo puedes dar una actuación (discurso, canción o baile) que inspire hasta 6 aliados (incluido tú) a 30 pies de ti que la presencien: cada uno gana PG temporales iguales a tu nivel de personaje + mod. de la característica aumentada con esta dote." },
  { n:"Keen Mind [PHB 2024]", tipo:"General", a:"B", alias:["Keen Mind [PHB'24]"], d:"Req. Nv.4+, INT 13+. +1 INT (máx. 20). Estudio Guiado: eliges Arcana, Historia, Investigación, Naturaleza o Religión; ganas competencia (o Pericia si ya la tienes). Estudio Rápido: realizas la acción Estudiar como Acción Adicional." },
  { n:"Lightly Armored [PHB 2024]", tipo:"General", alias:["Lightly Armored [PHB'14 / PHB'24]"], d:"Req. Nv.4+. +1 FUE o DES (máx. 20). Entrenamiento con Armadura Ligera y Escudos." },
  { n:"Mage Slayer [PHB 2024]", tipo:"General", a:"O", alias:["Mage Slayer [PHB'24]"], d:"Req. Nv.4+. +1 FUE o DES (máx. 20). Rompe-concentración: cuando dañas a una criatura que se concentra, tiene Desventaja en la salvación para mantener la concentración. Mente Protegida: si fallas una salvación de INT, SAB o CAR, puedes tener éxito en su lugar; no puedes volver a hacerlo hasta un Descanso Corto o Largo. [2014: ataque de reacción contra lanzadores adyacentes y Ventaja en salvaciones contra sus conjuros.]" },
  { n:"Martial Weapon Training [PHB 2024]", tipo:"General", alias:["Martial Weapon Training [PHB'24]"], d:"Req. Nv.4+. +1 FUE o DES (máx. 20). Competencia con las armas Marciales." },
  { n:"Medium Armor Master [PHB 2024]", tipo:"General", alias:["Medium Armor Master [PHB'24]"], d:"Req. Nv.4+, Entrenamiento con Armadura Media. +1 FUE o DES (máx. 20). Portador Diestro: con armadura media sumas 3 (en vez de 2) a tu CA si tu DES es 16 o más." },
  { n:"Moderately Armored [PHB 2024]", tipo:"General", alias:["Moderately Armored [PHB'24]"], d:"Req. Nv.4+, Entrenamiento con Armadura Ligera. +1 FUE o DES (máx. 20). Entrenamiento con Armadura Media." },
  { n:"Mounted Combatant [PHB 2024]", tipo:"General", alias:["Mounted Combatant [PHB'24]"], d:"Req. Nv.4+. +1 FUE, DES o SAB (máx. 20). Golpe Montado: montado, tienes Ventaja en ataques contra criaturas no montadas a 5 pies de tu montura que sean al menos un tamaño menor que ella. Salto Lateral: si tu montura debe hacer una salvación de DES para sufrir solo la mitad de daño, no sufre ninguno si la supera y solo la mitad si la falla. Para que tu montura obtenga este beneficio debes estar montado en ella y ninguno de los dos puede estar Incapacitado. Desvío: montado, puedes hacer que un ataque que impacta a tu montura te impacte a ti en su lugar (si no estás Incapacitado)." },
  { n:"Observant [PHB 2024]", tipo:"General", a:"B", alias:["Observant [PHB'24]"], d:"Req. Nv.4+, INT o SAB 13+. +1 INT o SAB (máx. 20). Observador Atento: eliges Investigación, Percepción o Perspicacia; ganas competencia (o Pericia si ya la tienes). Búsqueda Rápida: realizas la acción Buscar como Acción Adicional." },
  { n:"Piercer [PHB 2024 / TCE]", tipo:"General", alias:["Piercer [PHB'24]","Piercer [TCE]"], d:"Req. Nv.4+ (PHB 2024). +1 FUE o DES (máx. 20). Perforar: una vez por turno, al impactar con un ataque que inflige daño perforante, puedes repetir uno de los dados de daño y usar el nuevo resultado. Crítico: al causar un crítico con daño perforante, tiras un dado de daño adicional." },
  { n:"Poisoner [PHB 2024 / TCE]", tipo:"General", a:"B", alias:["Poisoner [PHB'24]","Poisoner [TCE]"], d:"Req. Nv.4+ (PHB 2024). +1 DES o INT (máx. 20). Veneno Potente: cuando haces una tirada de daño que inflige daño de veneno, ignora la Resistencia al daño de veneno. Elaborar Veneno: competencia con el Kit de Envenenador; con 1 hora y 50 po creas tantas dosis como tu bonificador de competencia. Aplicar una dosis a un arma o munición es una Acción Adicional y dura 1 minuto o hasta que inflija daño; el objetivo impactado hace una salvación de CON (CD 8 + mod. de la característica aumentada + comp.) o sufre 2d8 de daño de veneno y queda Envenenado hasta el final de tu siguiente turno. [TCE 2014: sin +1 a característica ni requisito de nivel; CD 14 fija.]" },
  { n:"Polearm Master [PHB 2024]", tipo:"General", a:"BR", alias:["Polearm Master [PHB'24]"], d:"Req. Nv.4+, FUE o DES 13+. +1 FUE o DES (máx. 20). Golpe con el Asta: tras la acción Atacar con un bastón, lanza o arma con Pesada y Alcance, usas una Acción Adicional para atacar con el extremo opuesto (1d4 contundente, mismo modificador). Ataque Reactivo: empuñando un bastón, lanza o arma con Pesada y Alcance, usas tu Reacción para hacer un ataque cuerpo a cuerpo contra una criatura que entre en tu alcance con esa arma." },
  { n:"Resilient [PHB 2024]", tipo:"General", alias:["Resilient [PHB'14 / PHB'24]"], d:"Req. Nv.4+. Eliges una característica en la que no tengas competencia en salvación: +1 a ella (máx. 20) y ganas competencia en sus salvaciones." },
  { n:"Ritual Caster [PHB 2024]", tipo:"General", alias:["Ritual Caster [PHB'24]"], d:"Req. Nv.4+, INT, SAB o CAR 13+. +1 INT, SAB o CAR (máx. 20). Conjuros de Ritual: eliges conjuros de nivel 1 con la etiqueta Ritual, tantos como tu bonificador de competencia; siempre preparados; puedes lanzarlos como ritual o con espacios; su característica de lanzamiento es la que aumentaste con esta dote. Cada vez que aumenta tu bonificador de competencia aprendes uno más. Ritual Rápido: puedes lanzar un conjuro de Ritual que tengas preparado con su tiempo de lanzamiento normal, sin el tiempo adicional de ritual y sin gastar espacio; no puedes volver a hacerlo hasta que termines un Descanso Largo. [2014: libro de rituales de una clase.]" },
  { n:"Sentinel [PHB 2024]", tipo:"General", a:"R", alias:["Sentinel [PHB'24]"], d:"Req. Nv.4+, FUE o DES 13+. +1 FUE o DES (máx. 20). Guardián: justo después de que una criatura a 5 pies realice la acción Retirarse o impacte a un objetivo que no seas tú, puedes hacerle un ataque de oportunidad. Detener: cuando impactas a una criatura con un ataque de oportunidad, su Velocidad pasa a 0 el resto del turno." },
  { n:"Shadow-Touched [PHB 2024 / TCE]", tipo:"General", a:"A", alias:["Shadow Touched [TCE / PHB'24]","Shadow-Touched [TCE / PHB'24]"], d:"Req. Nv.4+ (PHB 2024). +1 INT, SAB o CAR (máx. 20). Magia de las Sombras: aprendes Invisibility y 1 conjuro de nivel 1 de Ilusión o Nigromancia a tu elección; siempre preparados; puedes lanzar cada uno 1 vez por Descanso Largo sin espacio (o con espacios). Característica de lanzamiento: la que aumentaste. [TCE 2014: igual, sin requisito de nivel.]" },
  { n:"Sharpshooter [PHB 2024]", tipo:"General", alias:["Sharpshooter [PHB'24]"], d:"Req. Nv.4+, DES 13+. +1 DES (máx. 20). Ignorar Cobertura: tus ataques a distancia con arma ignoran Cobertura Media y de Tres Cuartos. Disparar en cuerpo a cuerpo: no sufres Desventaja al atacar a distancia a 5 pies de un enemigo. Tiros Largos: atacar a largo alcance no te impone Desventaja. [2014: –5 al ataque para +10 al daño.]" },
  { n:"Shield Master [PHB 2024]", tipo:"General", a:"R", alias:["Shield Master [PHB'24]"], d:"Req. Nv.4+, Entrenamiento con Escudos. +1 FUE (máx. 20). Golpe de Escudo: si atacas a una criatura a 5 pies como parte de la acción Atacar e impactas con un arma cuerpo a cuerpo, puedes golpear de inmediato al objetivo con tu escudo (si lo llevas equipado): el objetivo hace una salvación de FUE (CD 8 + mod. FUE + comp.) o lo empujas 5 pies o lo derribas (Tumbado), a tu elección. Solo una vez por turno. Interponer Escudo: si superas una salvación de DES que reduce el daño a la mitad, puedes usar tu Reacción con un escudo para no sufrir daño." },
  { n:"Skill Expert [PHB 2024 / TCE]", tipo:"General", alias:["Skill Expert [TCE / PHB'24]"], d:"Req. Nv.4+ (PHB 2024). +1 a una característica a tu elección (máx. 20). Ganas competencia en 1 habilidad y Pericia en 1 habilidad en la que ya seas competente. [TCE 2014: igual, sin requisito de nivel.]" },
  { n:"Skulker [PHB 2024]", tipo:"General", alias:["Skulker [PHB'24]"], d:"Req. Nv.4+, DES 13+. +1 DES (máx. 20). Vista Ciega 10 pies. Niebla de Guerra: Ventaja en las pruebas de DES (Sigilo) de la acción Esconderse mientras estés en combate. Francotirador: si fallas una tirada de ataque estando Oculto, el ataque no revela tu posición." },
  { n:"Slasher [PHB 2024 / TCE]", tipo:"General", alias:["Slasher [PHB'24]","Slasher [TCE]"], d:"Req. Nv.4+ (PHB 2024). +1 FUE o DES (máx. 20). Desjarretar: una vez por turno, al impactar con un ataque que inflige daño cortante, reduces la Velocidad del objetivo en 10 pies hasta el inicio de tu siguiente turno. Crítico: al causar un crítico con daño cortante, el objetivo tiene Desventaja en sus tiradas de ataque hasta el inicio de tu siguiente turno." },
  { n:"Speedy [PHB 2024]", tipo:"General", alias:["Speedy [PHB'24]"], d:"Req. Nv.4+, DES o CON 13+. +1 DES o CON (máx. 20). Tu Velocidad aumenta 10 pies. Al realizar la acción Correr ignoras el Terreno Difícil el resto del turno. Los ataques de oportunidad contra ti tienen Desventaja." },
  { n:"Spell Sniper [PHB 2024]", tipo:"General", alias:["Spell Sniper [PHB'24]"], d:"Req. Nv.4+, rasgo Lanzamiento de Conjuros o Magia de Pacto. +1 INT, SAB o CAR (máx. 20). Ignorar Cobertura: tus ataques de conjuro ignoran Cobertura Media y de Tres Cuartos. Lanzar en cuerpo a cuerpo: estar a 5 pies de un enemigo no impone Desventaja a tus ataques de conjuro a distancia. Alcance aumentado: los conjuros con tirada de ataque y alcance de 10 pies o más ven su alcance aumentado en 60 pies. [2014: alcance ×2 y un truco de ataque extra.]" },
  { n:"Telekinetic [PHB 2024 / TCE]", tipo:"General", a:"B", alias:["Telekinetic [PHB'24]","Telekinetic [TCE]"], d:"Req. Nv.4+ (PHB 2024). +1 INT, SAB o CAR (máx. 20). Telequinesia Menor: aprendes Mage Hand. Puedes lanzarlo sin componentes verbales ni somáticos y hacer invisible la mano espectral; al lanzarlo, su alcance y la distancia a la que la mano puede estar de ti aumentan 30 pies. [TCE 2014: el aumento de 30 pies al alcance solo se aplica si ya conocías Mage Hand.] La característica de lanzamiento de Mage Hand es la que aumentaste con esta dote. Empujón Telequinético: como Acción Adicional empujas a una criatura que veas a 30 pies: salvación de FUE (CD 8 + mod. de la característica aumentada + comp.) o la mueves 5 pies hacia ti o alejándola de ti." },
  { n:"Telepathic [PHB 2024 / TCE]", tipo:"General", a:"A", alias:["Telepathic [PHB'24]","Telepathic [TCE]"], d:"Req. Nv.4+ (PHB 2024). +1 INT, SAB o CAR (máx. 20). Expresión Telepática: hablas telepáticamente a una criatura que veas a 60 pies, en un idioma que conozcas (ella no puede responder telepáticamente). Detect Thoughts: siempre preparado; lo lanzas sin espacio de conjuro y sin componentes 1 vez por Descanso Largo (también puedes lanzarlo con espacios del nivel adecuado); característica de lanzamiento: la que aumentaste." },
  { n:"War Caster [PHB 2024]", tipo:"General", a:"R", alias:["War Caster [PHB'24]"], d:"Req. Nv.4+, rasgo Lanzamiento de Conjuros o Magia de Pacto. +1 INT, SAB o CAR (máx. 20). Concentración: Ventaja en las salvaciones de CON para mantener la concentración. Conjuro Reactivo: cuando una criatura provoca tu ataque de oportunidad al salir de tu alcance, puedes usar tu Reacción para lanzarle un conjuro (tiempo de lanzamiento de 1 acción, objetivo único). Componentes Somáticos: puedes hacerlos aunque tengas armas o escudo en las manos." },
  { n:"Weapon Master [PHB 2024]", tipo:"General", alias:["Weapon Master [PHB'24]"], d:"Req. Nv.4+. +1 FUE o DES (máx. 20). Propiedad de Maestría: puedes usar la propiedad de maestría de 1 tipo de arma Simple o Marcial con el que seas competente; al terminar un Descanso Largo puedes cambiar el tipo elegido. [2014: competencia con 4 armas.]" },

  /* ════════════════════════════════
     ESTILOS DE LUCHA (PHB 2024) — requieren el rasgo Estilo de Lucha de una clase
  ════════════════════════════════ */
  { n:"Fighting Style: Archery [PHB 2024]", tipo:"Estilo de Combate", alias:["Fighting Style: Archery [PHB'24]"], d:"Req. rasgo Estilo de Lucha. +2 a las tiradas de ataque con armas a distancia." },
  { n:"Fighting Style: Blind Fighting [PHB 2024]", tipo:"Estilo de Combate", alias:["Fighting Style: Blind Fighting [PHB'24]"], d:"Req. rasgo Estilo de Lucha. Tienes Vista Ciega con alcance de 10 pies." },
  { n:"Fighting Style: Defense [PHB 2024]", tipo:"Estilo de Combate", alias:["Fighting Style: Defense [PHB'24]"], d:"Req. rasgo Estilo de Lucha. +1 a la CA mientras llevas armadura ligera, media o pesada." },
  { n:"Fighting Style: Dueling [PHB 2024]", tipo:"Estilo de Combate", alias:["Fighting Style: Dueling [PHB'24]"], d:"Req. rasgo Estilo de Lucha. +2 al daño con un arma cuerpo a cuerpo empuñada con una sola mano y sin otras armas." },
  { n:"Fighting Style: Great Weapon Fighting [PHB 2024]", tipo:"Estilo de Combate", alias:["Fighting Style: Great Weapon Fighting [PHB'24]"], d:"Req. rasgo Estilo de Lucha. Al sacar 1 o 2 en un dado de daño de un ataque con arma cuerpo a cuerpo empuñada con dos manos, lo tratas como un 3. El arma debe tener A Dos Manos o Versátil." },
  { n:"Fighting Style: Interception [PHB 2024]", tipo:"Estilo de Combate", a:"R", alias:["Fighting Style: Interception [PHB'24]"], d:"Req. rasgo Estilo de Lucha. Cuando una criatura que veas impacta a otra a 5 pies de ti con una tirada de ataque, usas tu Reacción para reducir el daño en 1d10 + tu bonificador de competencia. Debes empuñar un escudo o un arma Simple o Marcial." },
  { n:"Fighting Style: Protection [PHB 2024]", tipo:"Estilo de Combate", a:"R", alias:["Fighting Style: Protection [PHB'24]"], d:"Req. rasgo Estilo de Lucha. Cuando una criatura que veas ataca a un objetivo que no seas tú a 5 pies de ti, usas tu Reacción para interponer tu escudo (debes empuñar uno): impones Desventaja a esa tirada de ataque y a todas las demás tiradas de ataque contra el objetivo hasta el inicio de tu siguiente turno, si sigues a 5 pies de él." },
  { n:"Fighting Style: Thrown Weapon Fighting [PHB 2024]", tipo:"Estilo de Combate", alias:["Fighting Style: Thrown Weapon Fighting [PHB'24]"], d:"Req. rasgo Estilo de Lucha. +2 al daño cuando impactas con una tirada de ataque a distancia usando un arma con la propiedad Arrojadiza. [2014: además puedes sacar un arma Arrojadiza como parte del ataque con ella.]" },
  { n:"Fighting Style: Two-Weapon Fighting [PHB 2024]", tipo:"Estilo de Combate", alias:["Fighting Style: Two-Weapon Fighting [PHB'24]"], d:"Req. rasgo Estilo de Lucha. Al hacer el ataque adicional de la propiedad Ligera, añades tu modificador de característica a su daño si no lo sumas ya." },
  { n:"Fighting Style: Unarmed Fighting [PHB 2024]", tipo:"Estilo de Combate", alias:["Fighting Style: Unarmed Fighting [PHB'24]"], d:"Req. rasgo Estilo de Lucha. Tus Golpes Desarmados infligen 1d6 + mod. FUE de daño contundente (1d8 si no empuñas armas ni escudo). Al inicio de cada uno de tus turnos puedes infligir 1d4 de daño contundente a una criatura que tengas agarrada." },

  /* ════════════════════════════════
     DONES ÉPICOS (PHB 2024) — requieren nivel 19+; +1 a una característica (máx. 30)
  ════════════════════════════════ */
  { n:"Boon of Combat Prowess [PHB 2024]", tipo:"Boon Épico", a:"O", alias:["Boon of Combat Prowess [PHB'24]"], d:"Req. Nv.19+. +1 a una característica (máx. 30). Puntería Insuperable: cuando fallas una tirada de ataque, puedes impactar en su lugar; no puedes volver a usarlo hasta el inicio de tu siguiente turno." },
  { n:"Boon of Dimensional Travel [PHB 2024]", tipo:"Boon Épico", a:"O", alias:["Boon of Dimensional Travel [PHB'24]"], d:"Req. Nv.19+. +1 a una característica (máx. 30). Pasos Parpadeantes: justo después de realizar la acción Atacar o la acción Magia, puedes teletransportarte hasta 30 pies a un espacio libre que veas." },
  { n:"Boon of Energy Resistance [PHB 2024]", tipo:"Boon Épico", a:"R", alias:["Boon of Energy Resistance [PHB'24]"], d:"Req. Nv.19+. +1 a una característica (máx. 30). Resistencias: Resistencia a 2 tipos de daño a elegir entre Ácido, Frío, Fuego, Relámpago, Necrótico, Veneno, Psíquico, Radiante y Trueno; puedes cambiar la elección al terminar un Descanso Largo. Redirección de Energía: cuando sufres daño de uno de esos tipos, puedes usar tu Reacción para dirigir daño del mismo tipo contra otra criatura que veas a 60 pies de ti y que no esté tras Cobertura Total: debe superar una salvación de DES (CD 8 + mod. CON + comp.) o sufrir daño igual a 2d12 + tu mod. CON." },
  { n:"Boon of Fate [PHB 2024]", tipo:"Boon Épico", a:"O", d:"Req. Nv.19+. +1 a una característica (máx. 30). Mejorar el Destino: cuando tú u otra criatura a 60 pies de ti supera o falla una Prueba de d20, puedes tirar 2d4 y aplicar el total como bonificador o penalizador a la tirada de d20. No puedes volver a usarlo hasta que tires iniciativa o termines un Descanso Corto o Largo." },
  { n:"Boon of Fortitude [PHB 2024]", tipo:"Boon Épico", alias:["Boon of Fortitude [PHB'24]"], d:"Req. Nv.19+. +1 a una característica (máx. 30). Salud Fortificada: tus PG máximos aumentan en 40; además, cuando recuperas PG puedes recuperar PG adicionales iguales a tu mod. CON. Una vez que los has recuperado, no puedes volver a hacerlo hasta el inicio de tu siguiente turno." },
  { n:"Boon of Irresistible Offense [PHB 2024]", tipo:"Boon Épico", alias:["Boon of Irresistible Offense [PHB'24]"], d:"Req. Nv.19+. +1 FUE o DES (máx. 30). Superar Defensas: el daño contundente, perforante y cortante que infliges ignora siempre la Resistencia. Golpe Arrollador: al sacar 20 natural en el d20 de una tirada de ataque, puedes infligir daño extra al objetivo igual al valor de la característica que aumentaste con esta dote (no su modificador); el daño extra es del mismo tipo que el ataque." },
  { n:"Boon of Recovery [PHB 2024]", tipo:"Boon Épico", a:"B", alias:["Boon of Recovery [PHB'24]"], d:"Req. Nv.19+. +1 a una característica (máx. 30). Última Resistencia: cuando fueras a quedar a 0 PG, puedes quedar a 1 PG en su lugar y recuperar PG iguales a la mitad de tus PG máximos; 1/Descanso Largo. Recuperar Vitalidad: tienes una reserva de 10d10; como Acción Adicional gastas los dados que quieras, los tiras y recuperas PG iguales al total; la reserva se restablece con un Descanso Largo." },
  { n:"Boon of Skill [PHB 2024]", tipo:"Boon Épico", alias:["Boon of Skill [PHB'24]"], d:"Req. Nv.19+. +1 a una característica (máx. 30). Formación Universal: ganas competencia en todas las habilidades. Maestría Especializada: ganas Pericia en 1 habilidad en la que aún no la tengas." },
  { n:"Boon of Speed [PHB 2024]", tipo:"Boon Épico", a:"B", alias:["Boon of Speed [PHB'24]"], d:"Req. Nv.19+. +1 a una característica (máx. 30). Tu Velocidad aumenta 30 pies. Artista del Escape: como Acción Adicional realizas la acción Retirarse, que además pone fin a la condición Agarrado que sufras." },
  { n:"Boon of Spell Recall [PHB 2024]", tipo:"Boon Épico", a:"O", alias:["Boon of Spell Recall [PHB'24]"], d:"Req. Nv.19+, rasgo Lanzamiento de Conjuros o Magia de Pacto. +1 INT, SAB o CAR (máx. 30). Lanzamiento Gratuito: cada vez que lanzas un conjuro con un espacio de nivel 1 a 4, tiras 1d4; si sale el nivel del espacio, éste no se gasta." },
  { n:"Boon of the Night Spirit [PHB 2024]", tipo:"Boon Épico", a:"B", d:"Req. Nv.19+. +1 a una característica (máx. 30). Fundirse con las Sombras: con Luz Tenue u Oscuridad, como Acción Adicional te vuelves Invisible; termina justo después de realizar una acción, Acción Adicional o Reacción. Forma de Sombra: con Luz Tenue u Oscuridad tienes Resistencia a todo el daño salvo Psíquico y Radiante." },
  { n:"Boon of Truesight [PHB 2024]", tipo:"Boon Épico", alias:["Boon of Truesight [PHB'24]"], d:"Req. Nv.19+. +1 a una característica (máx. 30). Tienes Visión Verdadera con alcance de 60 pies." },

  /* ════════════════════════════════
     DOTES DEL PHB 2014 (5e original) — sólo las que difieren de la versión 2024 o no existen en ella
  ════════════════════════════════ */
  { n:"Actor [PHB 2014]", tipo:"General (PHB 2014)", alias:["Actor [PHB'14]"], d:"+1 CAR (máx. 20). Ventaja en pruebas de CAR (Engaño) y (Interpretación) para hacerte pasar por otra persona. Puedes imitar el habla de alguien o los sonidos de una criatura tras oírlos durante al menos 1 minuto; quien lo oiga puede detectar la imitación con una prueba de SAB (Perspicacia) contra tu prueba de CAR (Engaño)." },
  { n:"Alert [PHB 2014]", tipo:"General (PHB 2014)", alias:["Alert [PHB'14]"], d:"+5 a la iniciativa. No puedes ser sorprendido mientras estés consciente. Las demás criaturas no obtienen Ventaja en sus ataques contra ti por estar ocultas." },
  { n:"Athlete [PHB 2014]", tipo:"General (PHB 2014)", alias:["Athlete [PHB'14]"], d:"+1 FUE o DES (máx. 20). Levantarte estando Tumbado sólo cuesta 5 pies de movimiento. Trepar no cuesta movimiento adicional. Haces saltos de longitud y altura con sólo 5 pies de carrerilla." },
  { n:"Charger [PHB 2014]", tipo:"General (PHB 2014)", a:"B", alias:["Charger [PHB'14]"], d:"Si realizas la acción Correr, puedes usar tu Acción Adicional para hacer un ataque cuerpo a cuerpo con arma o empujar a una criatura. Si te moviste al menos 10 pies en línea recta justo antes de esa Acción Adicional, ganas +5 al daño del ataque (si impactas) o empujas a la criatura hasta 10 pies (si lo consigues)." },
  { n:"Crossbow Expert [PHB 2014]", tipo:"General (PHB 2014)", a:"B", alias:["Crossbow Expert [PHB'14]"], d:"Ignoras la propiedad Carga de las ballestas con las que eres competente. Estar a 5 pies de un enemigo hostil no impone Desventaja a tus ataques a distancia. Si atacas con un arma de una mano en la acción Atacar, puedes usar una Acción Adicional para atacar con una ballesta de mano que empuñes." },
  { n:"Defensive Duelist [PHB 2014]", tipo:"General (PHB 2014)", a:"R", alias:["Defensive Duelist [PHB'14]"], d:"Req. DES 13+. Si empuñas un arma de Finura con la que seas competente y otra criatura te impacta con un ataque cuerpo a cuerpo, puedes usar tu Reacción para sumar tu bonificador de competencia a tu CA contra ese ataque, pudiendo hacerlo fallar." },
  { n:"Dual Wielder [PHB 2014]", tipo:"General (PHB 2014)", alias:["Dual Wielder [PHB'14]"], d:"+1 CA mientras empuñes un arma cuerpo a cuerpo distinta en cada mano. Puedes luchar con dos armas aunque no sean Ligeras. Puedes sacar o guardar dos armas de una mano en el momento en que sólo podrías con una." },
  { n:"Dungeon Delver [PHB 2014]", tipo:"General (PHB 2014)", alias:["Dungeon Delver [PHB'14]"], d:"Ventaja en pruebas de SAB (Percepción) e INT (Investigación) para detectar puertas secretas. Ventaja en las salvaciones para evitar trampas y Resistencia al daño que infligen. Viajar a ritmo rápido no te impone la penalización normal de –5 a tu Percepción pasiva (SAB)." },
  { n:"Durable [PHB 2014]", tipo:"General (PHB 2014)", alias:["Durable [PHB'14]"], d:"+1 CON (máx. 20). Cuando tiras un Dado de Golpe para recuperar PG, el mínimo que recuperas es el doble de tu modificador de CON (mínimo 2)." },
  { n:"Elemental Adept [PHB 2014]", tipo:"General (PHB 2014)", alias:["Elemental Adept [PHB'14]"], d:"Req. capacidad de lanzar al menos 1 conjuro. Eliges Ácido, Frío, Fuego, Relámpago o Trueno: tus conjuros ignoran la Resistencia a ese tipo y, al tirar su daño, tratas cada 1 como 2. Repetible con tipos distintos." },
  { n:"Grappler [PHB 2014]", tipo:"General (PHB 2014)", alias:["Grappler [PHB'14]"], d:"Req. FUE 13+. Ventaja en ataques contra una criatura que tengas agarrada. Como acción puedes intentar inmovilizarla (prueba de agarre): si lo consigues, tú y ella estáis Apresados hasta que termine el agarre." },
  { n:"Great Weapon Master [PHB 2014]", tipo:"General (PHB 2014)", a:"B", alias:["Great Weapon Master [PHB'14]"], d:"En tu turno, si causas un crítico o reduces a una criatura a 0 PG con un arma cuerpo a cuerpo, puedes hacer un ataque cuerpo a cuerpo con arma como Acción Adicional. Antes de hacer un ataque cuerpo a cuerpo con un arma Pesada con la que seas competente, puedes aceptar –5 a la tirada de ataque para infligir +10 de daño si impactas." },
  { n:"Healer [PHB 2014]", tipo:"General (PHB 2014)", a:"A", alias:["Healer [PHB'14]"], d:"Cuando estabilizas a una criatura con un Botiquín de Sanador, ésta recupera 1 PG. Como acción, gastas 1 uso del Botiquín de Sanador para atender a una criatura y restaurarle 1d6 + 4 PG, más PG adicionales iguales a su número máximo de Dados de Golpe; no puede recuperar PG de esta dote de nuevo hasta que termine un Descanso Corto o Largo." },
  { n:"Heavily Armored [PHB 2014]", tipo:"General (PHB 2014)", alias:["Heavily Armored [PHB'14]"], d:"Req. competencia con armadura media. +1 FUE (máx. 20). Competencia con armadura pesada." },
  { n:"Heavy Armor Master [PHB 2014]", tipo:"General (PHB 2014)", alias:["Heavy Armor Master [PHB'14]"], d:"Req. competencia con armadura pesada. +1 FUE (máx. 20). Mientras llevas armadura pesada, el daño contundente, perforante y cortante de armas no mágicas se reduce en 3." },
  { n:"Inspiring Leader [PHB 2014]", tipo:"General (PHB 2014)", a:"O", alias:["Inspiring Leader [PHB'14]"], d:"Req. CAR 13+. Dedicas 10 minutos a inspirar a hasta 6 criaturas amistosas (incluido tú) a 30 pies que puedan verte u oírte y que te entiendan: cada una puede ganar PG temporales iguales a tu nivel + tu mod. de CAR. Una criatura no puede ganar PG temporales de esta dote de nuevo hasta que termine un Descanso Corto o Largo." },
  { n:"Keen Mind [PHB 2014]", tipo:"General (PHB 2014)", alias:["Keen Mind [PHB'14]"], d:"+1 INT (máx. 20). Siempre sabes dónde está el norte y cuántas horas faltan para el próximo amanecer o atardecer. Recuerdas con precisión todo lo que has visto u oído en el último mes." },
  { n:"Lightly Armored [PHB 2014]", tipo:"General (PHB 2014)", d:"+1 FUE o DES (máx. 20). Competencia con armadura ligera." },
  { n:"Linguist [PHB 2014]", tipo:"General (PHB 2014)", alias:["Linguist [PHB'14]"], d:"+1 INT (máx. 20). Aprendes 3 idiomas a tu elección. Puedes crear mensajes cifrados: quien no conozca el cifrado necesita una prueba de INT (CD = tu puntuación de INT + tu bonificador de competencia) o magia para descifrarlos." },
  { n:"Lucky [PHB 2014]", tipo:"General (PHB 2014)", a:"O", alias:["Lucky [PHB'14]"], d:"Tienes 3 puntos de suerte (los recuperas con un Descanso Largo). Al hacer una tirada de ataque, prueba o salvación, puedes gastar 1 punto de suerte para tirar un d20 adicional. Puedes gastarlo después de tirar el dado, pero antes de conocer el resultado. Eliges cuál de los d20 se usa. También puedes gastar 1 punto cuando te hacen una tirada de ataque: tiras un d20 y eliges si el ataque usa el d20 del atacante o el tuyo. Si más de una criatura gasta un punto de suerte para influir en el resultado de la misma tirada, los puntos se anulan entre sí y no se tiran dados adicionales." },
  { n:"Mage Slayer [PHB 2014]", tipo:"General (PHB 2014)", a:"R", alias:["Mage Slayer [PHB'14]"], d:"Cuando una criatura a 5 pies de ti lanza un conjuro, puedes usar tu Reacción para hacerle un ataque cuerpo a cuerpo. Cuando dañas a una criatura que se concentra, tiene Desventaja en la salvación para mantener la concentración. Ventaja en salvaciones contra conjuros lanzados por criaturas a 5 pies de ti." },
  { n:"Magic Initiate [PHB 2014]", tipo:"General (PHB 2014)", alias:["Magic Initiate [PHB'14]"], d:"Eliges una clase: Bardo, Clérigo, Druida, Hechicero, Brujo o Mago. Aprendes 2 trucos y 1 conjuro de nivel 1 de su lista (con su característica de lanzamiento); puedes lanzar ese conjuro 1 vez por Descanso Largo sin espacio." },
  { n:"Martial Adept [PHB 2014]", tipo:"General (PHB 2014)", a:"O", alias:["Martial Adept [PHB'14]"], d:"Aprendes 2 maniobras del Maestro de Batalla (CD = 8 + comp. + mod. FUE o DES) y ganas 1 dado de superioridad (d6), que recuperas con un Descanso Corto o Largo." },
  { n:"Medium Armor Master [PHB 2014]", tipo:"General (PHB 2014)", alias:["Medium Armor Master [PHB'14]"], d:"Req. competencia con armadura media. La armadura media no te impone Desventaja en Sigilo. Con armadura media puedes sumar hasta +3 (en vez de +2) de tu modificador de DES a la CA." },
  { n:"Mobile [PHB 2014]", tipo:"General (PHB 2014)", alias:["Mobile [PHB'14]"], d:"Tu Velocidad aumenta 10 pies. Cuando realizas la acción Correr, el Terreno Difícil no te cuesta movimiento extra ese turno. Cuando haces un ataque cuerpo a cuerpo a una criatura (impactes o no), no provocas ataques de oportunidad de ella el resto del turno." },
  { n:"Moderately Armored [PHB 2014]", tipo:"General (PHB 2014)", alias:["Moderately Armored [PHB'14]"], d:"Req. competencia con armadura ligera. +1 FUE o DES (máx. 20). Competencia con armadura media y escudos." },
  { n:"Mounted Combatant [PHB 2014]", tipo:"General (PHB 2014)", alias:["Mounted Combatant [PHB'14]"], d:"Ventaja en ataques cuerpo a cuerpo contra criaturas no montadas más pequeñas que tu montura. Puedes obligar a que un ataque dirigido a tu montura te apunte a ti. Si tu montura supera una salvación de DES que reduce el daño a la mitad, no sufre daño; si la falla, sufre la mitad." },
  { n:"Observant [PHB 2014]", tipo:"General (PHB 2014)", alias:["Observant [PHB'14]"], d:"+1 INT o SAB (máx. 20). Si ves la boca de una criatura que habla un idioma que conoces, puedes leerle los labios. +5 a tu Percepción pasiva y a tu Investigación pasiva." },
  { n:"Polearm Master [PHB 2014]", tipo:"General (PHB 2014)", a:"BR", alias:["Polearm Master [PHB'14]"], d:"Si realizas la acción Atacar con una guja, alabarda, bastón o lanza, puedes usar una Acción Adicional para atacar con el extremo opuesto del arma (1d4 contundente, mismo modificador). Mientras empuñas una guja, alabarda, pica, bastón o lanza, las criaturas que entran en tu alcance con esa arma provocan un ataque de oportunidad tuyo." },
  { n:"Resilient [PHB 2014]", tipo:"General (PHB 2014)", d:"Eliges una característica: +1 a ella (máx. 20) y ganas competencia en sus salvaciones." },
  { n:"Ritual Caster [PHB 2014]", tipo:"General (PHB 2014)", alias:["Ritual Caster [PHB'14]"], d:"Req. INT o SAB 13+. Eliges una clase (Bardo, Clérigo, Druida, Hechicero, Brujo o Mago) y consigues un libro de rituales con 2 conjuros de nivel 1 con etiqueta Ritual de su lista. Puedes añadir rituales que encuentres (nivel máximo = la mitad de tu nivel, redondeando hacia arriba; 2 h y 50 po por nivel de conjuro). Sólo puedes lanzarlos como ritual, y debes tener el libro de rituales en la mano mientras lanzas uno de esos conjuros. Característica: INT (Mago), SAB (Clérigo, Druida) o CAR (Bardo, Hechicero, Brujo)." },
  { n:"Sentinel [PHB 2014]", tipo:"General (PHB 2014)", a:"R", alias:["Sentinel [PHB'14]"], d:"Cuando impactas a una criatura con un ataque de oportunidad, su Velocidad pasa a 0 el resto del turno. Las criaturas provocan tus ataques de oportunidad aunque realicen Retirarse. Cuando una criatura a 5 pies de ti ataca a un objetivo que no seas tú (y que no tenga esta dote), puedes usar tu Reacción para hacerle un ataque cuerpo a cuerpo con arma." },
  { n:"Sharpshooter [PHB 2014]", tipo:"General (PHB 2014)", alias:["Sharpshooter [PHB'14]"], d:"Atacar a largo alcance con armas a distancia no impone Desventaja. Tus ataques a distancia con arma ignoran Cobertura Media y de Tres Cuartos. Antes de atacar con un arma a distancia con la que seas competente, puedes aceptar –5 a la tirada de ataque para infligir +10 de daño si impactas." },
  { n:"Shield Master [PHB 2014]", tipo:"General (PHB 2014)", a:"BR", alias:["Shield Master [PHB'14]"], d:"Si realizas la acción Atacar, puedes usar una Acción Adicional para empujar con tu escudo a una criatura a 5 pies. Sumas el bonificador de CA del escudo a las salvaciones de DES contra efectos que sólo te tengan a ti como objetivo. Si superas una salvación de DES que reduce el daño a la mitad, puedes usar tu Reacción para no sufrir daño." },
  { n:"Skulker [PHB 2014]", tipo:"General (PHB 2014)", alias:["Skulker [PHB'14]"], d:"Req. DES 13+. Puedes intentar esconderte aunque sólo estés ligeramente oscurecido. Si fallas un ataque a distancia con arma desde oculto, no revelas tu posición. La luz tenue no te impone Desventaja en pruebas de Percepción basadas en la vista." },
  { n:"Spell Sniper [PHB 2014]", tipo:"General (PHB 2014)", alias:["Spell Sniper [PHB'14]"], d:"Req. capacidad de lanzar al menos 1 conjuro. Al lanzar un conjuro que requiere tirada de ataque, su alcance se duplica. Tus ataques de conjuro a distancia ignoran Cobertura Media y de Tres Cuartos. Aprendes un truco con tirada de ataque de la lista de una clase a tu elección (con la característica de lanzamiento de esa clase)." },
  { n:"Tavern Brawler [PHB 2014]", tipo:"General (PHB 2014)", a:"B", alias:["Tavern Brawler [PHB'14]"], d:"+1 FUE o CON (máx. 20). Competencia con armas improvisadas. Tus Golpes Desarmados infligen 1d4 + mod. FUE. Cuando impactas con un Golpe Desarmado o un arma improvisada en tu turno, puedes usar una Acción Adicional para intentar agarrar al objetivo." },
  { n:"War Caster [PHB 2014]", tipo:"General (PHB 2014)", a:"R", alias:["War Caster [PHB'14]"], d:"Req. capacidad de lanzar al menos 1 conjuro. Ventaja en salvaciones de CON para mantener la concentración. Puedes hacer componentes somáticos con armas o escudo en las manos. Cuando una criatura provoca tu ataque de oportunidad, puedes usar tu Reacción para lanzarle un conjuro (1 acción, objetivo único)." },
  { n:"Weapon Master [PHB 2014]", tipo:"General (PHB 2014)", alias:["Weapon Master [PHB'14]"], d:"+1 FUE o DES (máx. 20). Competencia con 4 armas simples o marciales a tu elección." },

  /* ════════════════════════════════
     DOTES DE XANATHAR'S GUIDE TO EVERYTHING (XGtE) — con requisito de linaje (2014)
  ════════════════════════════════ */
  { n:"Bountiful Luck [XGtE]", tipo:"General (XGtE)", a:"R", alias:["Bountiful Luck [XGE]"], d:"Req. Mediano. Cuando un aliado que veas a 30 pies saca un 1 en el d20 de un ataque, prueba o salvación, puedes usar tu Reacción para que repita la tirada; debe usar el nuevo resultado. Al usar esta capacidad, no puedes usar tu rasgo racial Suerte (Lucky) hasta el final de tu siguiente turno." },
  { n:"Dragon Fear [XGtE]", tipo:"General (XGtE)", a:"A", alias:["Dragon Fear [XGE]"], d:"Req. Dracónido. +1 CON, FUE o CAR (máx. 20). En lugar de exhalar con tu Arma de Aliento, puedes rugir: cada criatura que elijas a 30 pies hace una salvación de SAB (CD 8 + comp. + mod. CAR); la supera automáticamente si no puede oírte ni verte. Si falla, queda Asustada de ti 1 minuto; si sufre daño, repite la salvación y termina el efecto si la supera. Gastas un uso del Arma de Aliento." },
  { n:"Dragon Hide [XGtE]", tipo:"General (XGtE)", alias:["Dragon Hide [XGE]"], d:"Req. Dracónido. +1 CON, FUE o CAR (máx. 20). Garras retráctiles: extenderlas o retraerlas no requiere acción. Son armas naturales con las que haces ataques desarmados; si impactas, infliges daño cortante igual a 1d4 + mod. FUE en lugar del daño contundente normal. Escamas: mientras no lleves armadura, puedes calcular tu CA como 13 + mod. DES. Puedes usar escudo y mantener este beneficio." },
  { n:"Drow High Magic [XGtE]", tipo:"General (XGtE)", alias:["Drow High Magic [XGE]"], d:"Req. Elfo (drow). Lanzas Detect Magic a voluntad sin espacio. Lanzas Levitate y Dispel Magic 1 vez cada uno por Descanso Largo sin espacio (Dispel Magic con su nivel mínimo). Característica de lanzamiento: CAR." },
  { n:"Dwarven Fortitude [XGtE]", tipo:"General (XGtE)", alias:["Dwarven Fortitude [XGE]"], d:"Req. Enano. +1 CON (máx. 20). Cuando realizas la acción Esquivar en combate, puedes gastar 1 Dado de Golpe: lo tiras, sumas tu mod. CON y recuperas PG iguales al total (mínimo 1)." },
  { n:"Elven Accuracy [XGtE]", tipo:"General (XGtE)", alias:["Elven Accuracy [XGE]"], d:"Req. Elfo o Semielfo. +1 DES, INT, SAB o CAR (máx. 20). Cuando tienes Ventaja en una tirada de ataque con DES, INT, SAB o CAR, puedes volver a tirar uno de los dados una vez." },
  { n:"Fade Away [XGtE]", tipo:"General (XGtE)", a:"R", alias:["Fade Away [XGE]"], d:"Req. Gnomo. +1 DES o INT (máx. 20). Inmediatamente después de sufrir daño, puedes usar tu Reacción para volverte Invisible hasta el final de tu siguiente turno o hasta que ataques, infligas daño o fuerces una salvación. 1/Descanso Corto o Largo." },
  { n:"Fey Teleportation [XGtE]", tipo:"General (XGtE)", a:"B", alias:["Fey Teleportation [XGE]"], d:"Req. Elfo (alto elfo). +1 INT o CAR (máx. 20). Aprendes a hablar, leer y escribir Silvano (Sylvan) y el conjuro Misty Step, que lanzas 1 vez por Descanso Corto o Largo sin espacio (característica: INT)." },
  { n:"Flames of Phlegethos [XGtE]", tipo:"General (XGtE)", alias:["Flames of Phlegethos [XGE]"], d:"Req. Tiefling. +1 INT o CAR (máx. 20). Al tirar daño de fuego de un conjuro, puedes repetir cada 1 y usar el nuevo resultado. Cuando lanzas un conjuro que inflige daño de fuego, puedes envolverte en llamas hasta el final de tu siguiente turno: luz brillante 30 pies y tenue 30 más; quien te impacte con un ataque cuerpo a cuerpo a 5 pies sufre 1d4 de fuego." },
  { n:"Infernal Constitution [XGtE]", tipo:"General (XGtE)", alias:["Infernal Constitution [XGE]"], d:"Req. Tiefling. +1 CON (máx. 20). Resistencia al daño de frío y de veneno. Ventaja en salvaciones para evitar o terminar la condición Envenenado." },
  { n:"Orcish Fury [XGtE]", tipo:"General (XGtE)", a:"O", alias:["Orcish Fury [XGE]"], d:"Req. Semiorco. +1 FUE o CON (máx. 20). Una vez por Descanso Corto o Largo, al impactar con un arma simple o marcial puedes tirar uno de los dados de daño del arma una vez más y sumarlo. Además, justo después de usar Resistencia Implacable puedes usar tu Reacción para hacer un ataque con arma." },
  { n:"Prodigy [XGtE]", tipo:"General (XGtE)", alias:["Prodigy [XGE]"], d:"Req. Humano, Semielfo o Semiorco. Ganas competencia en 1 habilidad, 1 herramienta y 1 idioma a tu elección, y Pericia en 1 habilidad en la que seas competente (no puede ser una que ya duplique tu bonificador de competencia por otro rasgo, como Pericia)." },
  { n:"Second Chance [XGtE]", tipo:"General (XGtE)", a:"R", d:"Req. Mediano. +1 DES, CON o CAR (máx. 20). Cuando una criatura que veas te impacta con una tirada de ataque, puedes usar tu Reacción para obligarla a repetir la tirada. No puedes volver a usarlo hasta que tires iniciativa o termines un Descanso Corto o Largo." },
  { n:"Squat Nimbleness [XGtE]", tipo:"General (XGtE)", alias:["Squat Nimbleness [XGE]"], d:"Req. Enano o raza Pequeña. +1 FUE o DES (máx. 20). Tu Velocidad aumenta 5 pies. Ganas competencia en Acrobacias o Atletismo. Ventaja en pruebas de Acrobacias o Atletismo para escapar de un agarre." },
  { n:"Wood Elf Magic [XGtE]", tipo:"General (XGtE)", d:"Req. Elfo (elfo del bosque). Aprendes 1 truco de Druida (SAB) y lanzas Longstrider y Pass without Trace 1 vez cada uno por Descanso Largo sin espacio." },

  /* ════════════════════════════════
     DOTES DE TASHA'S CAULDRON OF EVERYTHING (TCE) — exclusivas de 2014 (las demás están fusionadas con su versión PHB 2024)
  ════════════════════════════════ */
  { n:"Artificer Initiate [TCE]", tipo:"General (TCE)", alias:["Artificer Initiate [TCE]"], d:"Aprendes 1 truco y 1 conjuro de nivel 1 de la lista de Artificiero (característica: INT); lanzas el de nivel 1 una vez por Descanso Largo sin espacio (o con espacios). Ganas competencia con 1 tipo de Herramientas de Artesano a tu elección, que puedes usar como foco de lanzamiento para cualquier conjuro que lances y que use INT como característica de lanzamiento." },
  { n:"Eldritch Adept [TCE]", tipo:"General (TCE)", alias:["Eldritch Adept [TCE]"], d:"Req. rasgo Lanzamiento de Conjuros o Magia de Pacto. Aprendes 1 Invocación Sobrenatural (Eldritch Invocation) de la clase Brujo a tu elección. Si la invocación tiene algún requisito, solo puedes elegirla si eres Brujo y lo cumples. Tu característica de lanzamiento para la invocación es INT, SAB o CAR (a tu elección al obtener la dote). Cada vez que subes de nivel puedes sustituirla por otra invocación de Brujo." },
  { n:"Fighting Initiate [TCE]", tipo:"General (TCE)", alias:["Fighting Initiate [TCE]"], d:"Req. competencia con un arma marcial. Aprendes 1 opción de Estilo de Lucha de la clase Guerrero; si ya tienes un Estilo de Lucha, el que elijas debe ser distinto. Cada vez que alcanzas un nivel que otorga Mejora de Característica (Ability Score Improvement), puedes sustituir el Estilo de Lucha de esta dote por otro de la clase Guerrero que no tengas." },
  { n:"Gunner [TCE]", tipo:"General (TCE)", alias:["Gunner [TCE]"], d:"+1 DES (máx. 20). Competencia con armas de fuego. Ignoras la propiedad Carga de las armas de fuego. Estar a 5 pies de una criatura hostil no impone Desventaja a tus tiradas de ataque a distancia." },
  { n:"Metamagic Adept [TCE]", tipo:"General (TCE)", alias:["Metamagic Adept [TCE]"], d:"Req. rasgo Lanzamiento de Conjuros o Magia de Pacto. Aprendes 2 opciones de Metamagia del Hechicero. Solo puedes usar una opción de Metamagia en un conjuro al lanzarlo, salvo que la opción indique lo contrario. Cada vez que alcanzas un nivel que otorga Mejora de Característica (Ability Score Improvement), puedes sustituir una de estas opciones de Metamagia por otra del Hechicero. Ganas 2 puntos de hechicería para usarlos sólo en Metamagia (los recuperas con un Descanso Largo)." },

  /* ════════════════════════════════
     FIZBAN'S TREASURY OF DRAGONS (FTD) y STRIXHAVEN (SCC)
  ════════════════════════════════ */
  { n:"Gift of the Chromatic Dragon [FTD]", tipo:"General (FTD)", a:"BR", alias:["Gift of the Chromatic Dragon [FTD]"], d:"Infusión Cromática (Chromatic Infusion): 1/Descanso Largo, como Acción Adicional infundes un arma Simple o Marcial que toques con Ácido, Frío, Fuego, Relámpago o Veneno durante 1 minuto: +1d4 de daño de ese tipo cuando impacta. Resistencia Reactiva: tantas veces por Descanso Largo como tu bonificador de competencia, cuando sufres daño de Ácido, Frío, Fuego, Relámpago o Veneno, usas tu Reacción para obtener Resistencia a ese daño." },
  { n:"Gift of the Gem Dragon [FTD]", tipo:"General (FTD)", a:"R", alias:["Gift of the Gem Dragon [FTD]"], d:"+1 INT, SAB o CAR (máx. 20). Represalia Telequinética: tantas veces por Descanso Largo como tu bonificador de competencia, cuando una criatura a 10 pies te daña, usas tu Reacción para forzarla a una salvación de FUE (CD 8 + comp. + mod. de la característica aumentada): si falla, sufre 2d8 de daño de fuerza y la empujas hasta 10 pies; si la supera, sufre la mitad del daño y no es empujada." },
  { n:"Gift of the Metallic Dragon [FTD]", tipo:"General (FTD)", a:"AR", alias:["Gift of the Metallic Dragon [FTD]"], d:"Curación Dracónica (Draconic Healing): aprendes Cure Wounds y lo lanzas 1 vez por Descanso Largo sin espacio; también puedes lanzarlo con espacios de conjuro (característica: INT, SAB o CAR a tu elección al obtener la dote). Alas Protectoras: tantas veces por Descanso Largo como tu bonificador de competencia, cuando tú u otra criatura que veas a 5 pies de ti es impactada por una tirada de ataque, usas tu Reacción para sumar tu bonificador de competencia a la CA del objetivo contra ese ataque (puede hacerlo fallar)." },
  { n:"Strixhaven Initiate [SCC]", tipo:"General (SCC)", alias:["Strixhaven Initiate [SCC]"], d:"Eliges un colegio de Strixhaven y aprendes 2 trucos y 1 conjuro de nivel 1 según esta tabla; lanzas el de nivel 1 una vez por Descanso Largo sin espacio (o con espacios). Lorehold: 2 trucos entre Light, Sacred Flame y Thaumaturgy; conjuro de nivel 1 de Clérigo o Mago. Prismari: 2 entre Fire Bolt, Prestidigitation y Ray of Frost; nivel 1 de Bardo o Hechicero. Quandrix: 2 entre Druidcraft, Guidance y Mage Hand; nivel 1 de Druida o Mago. Silverquill: 2 entre Sacred Flame, Thaumaturgy y Vicious Mockery; nivel 1 de Bardo o Clérigo. Witherbloom: 2 entre Chill Touch, Druidcraft y Spare the Dying; nivel 1 de Druida o Mago. Característica de lanzamiento: INT, SAB o CAR (a tu elección al obtener la dote)." },

  /* ═══════════════════════════════════════════
     ASTARION’S BOOK OF HUNGERS (ABH, 2024)
  ═══════════════════════════════════════════ */
  { n:"Bloodlust [ABH 2024]", tipo:"General (ABH 2024)", a:"O", d:"Req. Nv.4+. +1 FUE, DES o CON (máx. 20). Recuperación Poderosa (Powerful Recovery): al tirar un Dado de Golpe para recuperar PG, puedes tratar un 1 o un 2 como un 3. Festín Sanguíneo (Sanguine Feast): una vez por turno, al impactar con una tirada de ataque a una criatura Ensangrentada (Bloodied) que no sea Constructo ni No-Muerto, puedes gastar un Dado de Golpe, tirarlo y recuperar PG iguales al resultado + tu mod. CON. Puedes usar este rasgo tantas veces como tu bonificador de competencia y recuperas todos los usos al terminar un Descanso Largo." },
  { n:"Bomber [ABH 2024]", tipo:"General (ABH 2024)", d:"Req. Nv.4+. +1 DES (máx. 20). Lanzador Lejano (Far Lobber): al usar la acción Atacar para lanzar un vial o frasco, puedes elegir como objetivo un objeto o criatura que veas a 40 pies de ti. Tiros Largos (Long Shots): atacar a largo alcance no impone Desventaja a tus tiradas de ataque con armas Arrojadizas." },
  { n:"Boon of Blazing Dawn [ABH 2024]", tipo:"Boon Épico (ABH 2024)", a:"O", d:"Req. Nv.19+. +1 a una característica (máx. 30). Amado por el Sol (Beloved of the Sun): Inmune al daño Radiante. Golpe Resplandeciente (Blazing Strike): al impactar a una criatura con un ataque con arma, el daño puede ser Radiante o el tipo de daño normal del arma (a tu elección). Estallido de Luz Solar (Burst of Sunlight): una vez por turno, al impactar a una criatura con un ataque que inflige daño Radiante, puedes emitir Luz Brillante en un radio de 30 pies desde ti y Luz Tenue otros 30 pies más, hasta el inicio de tu siguiente turno; esta luz es luz solar." },
  { n:"Boon of Looming Shadows [ABH 2024]", tipo:"Boon Épico (ABH 2024)", a:"B", d:"Req. Nv.19+. +1 a una característica (máx. 30). Estirón de Sombra (Shadowy Stretch): al realizar la acción Atacar, el alcance de tus ataques cuerpo a cuerpo con arma aumenta 10 pies hasta el final de tu turno. Silueta Danzante (Dancing Silhouette): puedes realizar la acción Esquivar como Acción Adicional." },
  { n:"Boon of Misty Escape [ABH 2024]", tipo:"Boon Épico (ABH 2024)", a:"O", d:"Req. Nv.19+. +1 INT, SAB o CAR (máx. 30). Forma Gaseosa (Gaseous Form): si caes a 0 PG pero no mueres de golpe, puedes quedar en su lugar a 1 PG y lanzar Gaseous Form sin gastar espacio de conjuro (sin acción). Al lanzarlo así, solo puedes elegirte a ti, tu Velocidad de vuelo es de 20 pies y recuperas 10 PG al inicio de cada uno de tus turnos mientras dure el conjuro. La característica de lanzamiento del conjuro es la que aumentaste con esta dote. Una vez usado, no puedes volver a hacerlo hasta terminar un Descanso Largo." },
  { n:"Cloying Mists [ABH 2024]", tipo:"General (ABH 2024)", a:"A", d:"Req. Nv.4+. +1 INT, SAB o CAR (máx. 20). Álzate, Niebla (Arise, Fog): siempre tienes preparado Fog Cloud; puedes lanzarlo sin gastar espacio de conjuro y debes terminar un Descanso Largo antes de volver a lanzarlo así; también puedes lanzarlo con espacios de conjuro del nivel adecuado. Característica de lanzamiento: la que aumentaste con esta dote. Bruma Aferradora (Grasping Mist): al lanzar Fog Cloud, las llamas no mágicas en la esfera del conjuro se apagan y las criaturas que no sean tú ni tus aliados sufren una reducción de 5 pies de Velocidad mientras estén en la esfera." },
  { n:"Delicious Pain [ABH 2024]", tipo:"General (ABH 2024)", a:"R", d:"Req. Nv.4+. +1 a una característica (máx. 20). Carne Curtida (Toughened Flesh): justo después de sufrir daño Contundente, Perforante o Cortante, puedes usar una Reacción para ganar Resistencia al daño Contundente, Perforante y Cortante hasta el inicio de tu siguiente turno. Una vez usado, no puedes volver a hacerlo hasta terminar un Descanso Corto o Largo." },
  { n:"Light Bringer [ABH 2024]", tipo:"General (ABH 2024)", a:"AB", d:"Req. Nv.4+. +1 INT, SAB o CAR (máx. 20). Magia Sagrada (Sacred Magic): aprendes el truco Light y puedes lanzarlo sin componentes Materiales; si ya lo conoces, aprendes otro truco de Clérigo a tu elección. Característica de lanzamiento del conjuro: la que aumentaste con esta dote. Luminancia Solar (Solar Luminance): al lanzar Light, puedes hacer que su luz sea luz solar; una vez usado, no puedes volver a hacerlo hasta terminar un Descanso Largo. Curación del Sol (Sun’s Healing): como Acción Adicional, estando bajo luz solar, puedes gastar un Dado de Golpe, tirarlo y recuperar PG iguales al resultado; una vez usado, no puedes volver a hacerlo hasta terminar un Descanso Corto o Largo." },
  { n:"Love Bites [ABH 2024]", tipo:"General (ABH 2024)", a:"B", d:"Req. Nv.4+. +1 a una característica (máx. 20). Dolor Entrañable (Endearing Pain): justo después de dañar a una criatura con un arma cuerpo a cuerpo o un Golpe Desarmado, puedes usar una Acción Adicional para dejar al objetivo Hechizado hasta el inicio de tu siguiente turno o hasta que tú o tus aliados lo dañéis. Una vez usado, no puedes volver a hacerlo hasta terminar un Descanso Corto o Largo." },
  { n:"Putrefy [ABH 2024]", tipo:"General (ABH 2024)", a:"O", d:"Req. Nv.4+. +1 a una característica (máx. 20). Necrosis (Necrosis): al hacer una tirada de daño que inflige daño Necrótico, puedes hacer que una criatura que sufra ese daño quede Envenenada hasta el inicio de tu siguiente turno. Una vez usado, no puedes volver a hacerlo hasta terminar un Descanso Corto o Largo." },
  { n:"Rebuke [ABH 2024]", tipo:"General (ABH 2024)", a:"O", d:"Req. Nv.4+. +1 a una característica (máx. 20). Golpe Radiante (Radiant Strike): al hacer una tirada de daño que inflige daño Radiante, puedes hacer que una criatura Enorme o menor que sufra ese daño quede Tumbada. Una vez usado, no puedes volver a hacerlo hasta terminar un Descanso Corto o Largo." },
  { n:"Tireless Reveler [ABH 2024]", tipo:"Origen (ABH 2024)", a:"O", d:"Juerguista Incansable (Tireless Reveler): cuando un aliado que veas a 60 pies de ti gasta Inspiración Heroica, puedes ganar Inspiración Heroica si no la tienes. Puedes usar este beneficio tantas veces como tu bonificador de competencia y recuperas todos los usos al terminar un Descanso Corto o Largo." },
  { n:"Treacherous Allure [ABH 2024]", tipo:"General (ABH 2024)", a:"A", d:"Req. Nv.4+. +1 INT, SAB o CAR (máx. 20). Presencia Encantadora (Enchanting Presence): siempre tienes preparado Charm Person; puedes lanzarlo sin gastar espacio de conjuro y debes terminar un Descanso Largo antes de volver a lanzarlo así; también puedes lanzarlo con espacios de conjuro del nivel adecuado. Característica de lanzamiento: la que aumentaste con esta dote. Traición Inevitable (Inevitable Betrayal): tienes Ventaja en las tiradas de ataque contra criaturas Hechizadas." },
  { n:"Vampire Hunter [ABH 2024]", tipo:"Origen (ABH 2024)", a:"R", d:"Escape Habilidoso (Adroit Escape): Ventaja en las pruebas para escapar de ataduras no mágicas o de la condición Agarrado. Protección Vital (Vitality Ward): al sufrir daño Necrótico, puedes usar una Reacción para mitigarlo: tira tantos d6 como tu bonificador de competencia, suma los resultados y reduce el daño Necrótico que sufres en ese total. Una vez usado, no puedes volver a hacerlo hasta terminar un Descanso Corto o Largo." },
  { n:"Vampire Touched [ABH 2024]", tipo:"General (ABH 2024)", a:"O", d:"Req. Nv.4+. +1 INT, SAB o CAR (máx. 20). Magia Vampírica (Vampire Magic): eliges un conjuro de nivel 1 de la escuela de Encantamiento o Ilusión. Siempre tienes preparados ese conjuro y Spider Climb. Puedes lanzar cada uno sin gastar espacio de conjuro, pero al lanzar Spider Climb así debes elegirte a ti como objetivo, y debes terminar un Descanso Largo antes de volver a lanzar cada uno de esta forma. También puedes lanzar cualquiera de los dos con espacios de conjuro del nivel adecuado. Característica de lanzamiento: la que aumentaste con esta dote." },
  { n:"Vampire's Plaything [ABH 2024]", tipo:"Origen (ABH 2024)", a:"B", d:"Decantación (Decanting): al terminar un Descanso Largo, si tienes un vial o frasco vacío, puedes crear una Potion of Healing o un Antitoxin; estos líquidos se evaporan al terminar otro Descanso Largo. Retirada Oportuna (Timely Retreat): puedes usar una Acción Adicional para realizar la acción Correr o la acción Retirarse; puedes usar este beneficio tantas veces como tu bonificador de competencia y recuperas todos los usos al terminar un Descanso Largo. Conexión Vampírica (Vampiric Connection): el DM determina el destino de tu antiguo amo vampiro. Mientras tú y él estéis en el mismo plano de existencia, el vampiro puede comunicarse contigo telepáticamente y tú puedes elegir permitirle percibir a través de tus sentidos." },

  /* ═══════════════════════════════════════════
     THE BOOK OF MANY THINGS (BMT)
  ═══════════════════════════════════════════ */
  { n:"Cartomancer [BMT]", tipo:"General (BMT)", a:"B", d:"Req. Nv.4+, rasgo Lanzamiento de Conjuros o Magia de Pacto. Puedes usar una baraja de cartas como foco de lanzamiento. Trucos de Cartas (Card Tricks): aprendes el truco Prestidigitation y puedes usarlo para crear ilusiones que imitan los efectos de la magia escénica; al hacerlo, puedes disimular los componentes verbales y somáticos del conjuro como conversación y manejo de cartas normales. As Oculto (Hidden Ace): al terminar un Descanso Largo puedes elegir un conjuro de la lista de conjuros de tu clase e imbuirlo en una carta; debe tener un tiempo de lanzamiento de 1 acción y ser de un nivel para el que tengas espacios de conjuro. La carta permanece imbuida 8 horas; mientras lo esté, puedes usar una Acción Adicional para exhibirla y lanzar el conjuro que contiene, tras lo cual la carta pierde su magia de inmediato." },

  /* ═══════════════════════════════════════════
     BIGBY PRESENTS: GLORY OF THE GIANTS (BGotG)
  ═══════════════════════════════════════════ */
  { n:"Ember of the Fire Giant [BGotG]", tipo:"General (BGotG)", a:"A", d:"Req. Nv.4+, dote Strike of the Giants (Fire Strike). +1 FUE, CON o SAB (máx. 20). Nacido de las Llamas (Born of Flame): Resistencia al daño de Fuego. Ignición Abrasadora (Searing Ignition): al realizar la acción Atacar en tu turno, puedes sustituir un solo ataque por una ráfaga mágica de llamas: cada criatura de tu elección en una esfera de 15 pies de radio centrada en ti hace una salvación de DES (CD 8 + comp. + mod. de la característica aumentada con esta dote). Si falla, sufre daño de fuego igual a 1d8 + tu bonificador de competencia y queda Cegado hasta el inicio de tu siguiente turno; si la supera, sufre solo la mitad del daño. Puedes usar Ignición Abrasadora tantas veces como tu bonificador de competencia (máx. una vez por turno) y recuperas todos los usos al terminar un Descanso Largo." },
  { n:"Fury of the Frost Giant [BGotG]", tipo:"General (BGotG)", a:"R", d:"Req. Nv.4+, dote Strike of the Giants (Frost Strike). +1 FUE, CON o SAB (máx. 20). Nacido del Hielo (Born of Ice): Resistencia al daño de Frío. Represalia Gélida (Frigid Retaliation): justo después de que una criatura que veas a 30 pies de ti te impacte con una tirada de ataque y te inflija daño, puedes usar tu Reacción para responder con una ráfaga de hielo conjurada: la criatura hace una salvación de CON (CD 8 + comp. + mod. de la característica aumentada con esta dote); si falla, sufre daño de frío igual a 1d8 + tu bonificador de competencia y su Velocidad se reduce a 0 hasta el final de su siguiente turno. Puedes usar esta Reacción tantas veces como tu bonificador de competencia y recuperas todos los usos al terminar un Descanso Largo." },
  { n:"Guile of the Cloud Giant [BGotG]", tipo:"General (BGotG)", a:"R", d:"Req. Nv.4+, dote Strike of the Giants (Cloud Strike). +1 FUE, CON o CAR (máx. 20). Escape Nuboso (Cloudy Escape): cuando una criatura que veas te impacta con una tirada de ataque, puedes usar tu Reacción para ganar Resistencia al daño de ese ataque; después te teletransportas a un espacio libre que veas a 30 pies de ti. Puedes usar esta Reacción tantas veces como tu bonificador de competencia y recuperas todos los usos al terminar un Descanso Largo." },
  { n:"Keenness of the Stone Giant [BGotG]", tipo:"General (BGotG)", a:"B", d:"Req. Nv.4+, dote Strike of the Giants (Stone Strike). +1 FUE, CON o SAB (máx. 20). Vista de las Cavernas (Cavernous Sight): ganas Visión en la Oscuridad con alcance de 60 pies; si ya la tienes por otra fuente, su alcance aumenta 60 pies. Lanzamiento de Roca (Stone Throw): como Acción Adicional, puedes coger una roca y hacer con ella un ataque mágico: es una tirada de ataque de conjuro a distancia con alcance de 60 pies que usa como característica de lanzamiento la que aumentaste con esta dote. Si impacta, la roca inflige 1d10 de daño de fuerza y el objetivo debe superar una salvación de FUE (CD 8 + comp. + mod. de la característica de lanzamiento) o quedar Tumbado. Puedes usar esta Acción Adicional tantas veces como tu bonificador de competencia y recuperas todos los usos al terminar un Descanso Largo." },
  { n:"Rune Shaper [BGotG]", tipo:"General (BGotG)", a:"O", d:"Req. rasgo Lanzamiento de Conjuros o Magia de Pacto, o trasfondo Rune Carver. Comprender Idiomas (Comprehend Languages): aprendes el conjuro Comprehend Languages; puedes lanzarlo sin gastar espacio de conjuro y debes terminar un Descanso Largo antes de volver a lanzarlo así; también puedes lanzarlo con cualquier espacio de conjuro que tengas. Magia de Runas (Rune Magic): conoces tantas runas como la mitad de tu bonificador de competencia (redondeando hacia abajo), elegidas de la tabla de Conjuros de Runa. Al terminar un Descanso Largo, puedes inscribir cada runa que conozcas en un arma, armadura, prenda u otro objeto no mágico que toques. Aprendes temporalmente los conjuros de nivel 1 correspondientes a las runas inscritas y los conoces hasta que termines un Descanso Largo, cuando las runas se desvanecen. Mientras llevas o portas un objeto marcado con runas, puedes lanzar los conjuros asociados con cualquier espacio de conjuro que tengas. También puedes invocar una runa inscrita en un objeto que lleves o portes y lanzar su conjuro asociado sin gastar espacio de conjuro ni usar componentes materiales; tras lanzarlo así, no puedes volver a hacerlo hasta terminar un Descanso Largo. Característica de lanzamiento: INT, SAB o CAR (a elegir al obtener la dote). Cada vez que subes de nivel, puedes sustituir una de las runas que conoces por otra de la tabla. Conjuros de Runa (runa: conjuro): Nube (Cloud): Fog Cloud; Muerte (Death): Inflict Wounds; Dragón (Dragon): Chromatic Orb; Enemigo (Enemy): Disguise Self; Fuego (Fire): Burning Hands; Amigo (Friend): Speak with Animals; Escarcha (Frost): Armor of Agathys; Colina (Hill): Goodberry; Viaje (Journey): Longstrider; Rey (King): Command; Montaña (Mountain): Entangle; Piedra (Stone): Sanctuary; Tormenta (Storm): Thunderwave." },
  { n:"Soul of the Storm Giant [BGotG]", tipo:"General (BGotG)", a:"B", d:"Req. Nv.4+, dote Strike of the Giants (Storm Strike). +1 FUE, SAB o CAR (máx. 20). Aura de Torbellino (Maelstrom Aura): como Acción Adicional, te rodeas de un aura de viento y relámpagos mágicos que se extiende 10 pies desde ti en todas direcciones, pero no atraviesa Cobertura Total. Dura hasta el inicio de tu siguiente turno o hasta que quedes Incapacitado. Mientras está activa, tienes Resistencia al daño de relámpago y trueno, las tiradas de ataque contra ti tienen Desventaja y, cada vez que otra criatura empieza su turno dentro del aura, puedes obligarla a hacer una salvación de FUE (CD 8 + comp. + mod. de la característica aumentada con esta dote): si falla, su Velocidad se reduce a la mitad hasta el inicio de su siguiente turno. Puedes usar esta Acción Adicional tantas veces como tu bonificador de competencia y recuperas todos los usos al terminar un Descanso Largo." },
  { n:"Strike of the Giants [BGotG]", tipo:"General (BGotG)", a:"O", d:"Req. competencia con un arma marcial, o trasfondo Giant Foundling. Al obtener la dote eliges uno de los beneficios siguientes. Una vez por turno, al impactar a un objetivo con un ataque cuerpo a cuerpo con arma o con un ataque a distancia con un arma Arrojadiza, puedes imbuir el ataque con un efecto adicional según el beneficio elegido. Golpe de Nube (Cloud Strike): el objetivo sufre 1d4 de daño de trueno extra; si es una criatura, debe superar una salvación de SAB o te vuelves Invisible para ella hasta el inicio de tu siguiente turno o hasta justo después de que hagas una tirada de ataque o lances un conjuro. Golpe de Fuego (Fire Strike): el objetivo sufre 1d10 de daño de fuego extra. Golpe de Escarcha (Frost Strike): el objetivo sufre 1d6 de daño de frío extra; si es una criatura, debe superar una salvación de CON o su Velocidad se reduce a 0 hasta el inicio de tu siguiente turno. Golpe de Colina (Hill Strike): el objetivo sufre 1d6 de daño extra del tipo del arma; si es una criatura, debe superar una salvación de FUE o queda Tumbado. Golpe de Piedra (Stone Strike): el objetivo sufre 1d6 de daño de fuerza extra; si es una criatura, debe superar una salvación de FUE o es empujado 10 pies en línea recta alejándose de ti. Golpe de Tormenta (Storm Strike): el objetivo sufre 1d6 de daño de relámpago extra; si es una criatura, debe superar una salvación de CON o tiene Desventaja en las tiradas de ataque hasta el inicio de tu siguiente turno. La CD de estas salvaciones es 8 + tu bonificador de competencia + tu mod. FUE o CON. Puedes usar esta dote tantas veces como tu bonificador de competencia y recuperas todos los usos al terminar un Descanso Largo." },
  { n:"Vigor of the Hill Giant [BGotG]", tipo:"General (BGotG)", a:"R", d:"Req. Nv.4+, dote Strike of the Giants (Hill Strike). +1 FUE, CON o SAB (máx. 20). Baluarte (Bulwark): cuando te afecte un efecto que te movería al menos 5 pies o te dejaría Tumbado, puedes usar tu Reacción para afianzarte: no te mueves y no quedas Tumbado. Estómago de Hierro (Iron Stomach): siempre que comas como parte de un Descanso Corto y gastes uno o más Dados de Golpe para recuperar PG, recuperas PG adicionales iguales a tu mod. CON + tu bonificador de competencia." },

  /* ═══════════════════════════════════════════
     EBERRON: FORGE OF THE ARTIFICER (EFotA, 2024)
  ═══════════════════════════════════════════ */
  { n:"Aberrant Dragonmark [EFotA 2024]", tipo:"Dragonmark (EFotA 2024)", a:"AR", d:"Req. Campaña de Eberron; no tener otra dote Dragonmark. Fortaleza Aberrante (Aberrant Fortitude): al fallar una salvación de CON, puedes usar tu Reacción para tirar 1d4 y sumarlo a la salvación, lo que puede convertir el fallo en éxito; no puedes volver a usarlo hasta que termines un Descanso Largo. Magia Aberrante (Aberrant Magic): conoces 1 truco de la lista de conjuros de Hechicero a tu elección; además eliges 1 conjuro de nivel 1 de esa lista, que siempre tienes preparado; puedes lanzarlo 1 vez sin espacio de conjuro y recuperas ese uso al terminar un Descanso Corto o Largo; también puedes lanzarlo con espacios de conjuro. Característica de lanzamiento: CON. Oleada Aberrante (Aberrant Surge): al lanzar el conjuro de nivel 1 de esta dote, puedes gastar 1 Dado de Golpe y tirarlo: si sale par, ganas PG temporales iguales al resultado; si sale impar, una criatura a 30 pies de ti (que no seas tú) sufre daño de Fuerza igual al resultado; si no hay otras criaturas en alcance, el daño lo sufres tú." },
  { n:"Boon of Siberys [EFotA 2024]", tipo:"Boon Épico (EFotA 2024)", a:"O", d:"Req. Nv.19+, campaña de Eberron. +1 a una característica (máx. 30). Magia Aberrante (Aberrant Magic): eliges 1 conjuro de nivel 8 o inferior de la lista de conjuros de Hechicero o de la tabla Siberys Dragonmark Spells; siempre lo tienes preparado; puedes lanzarlo 1 vez sin espacio de conjuro ni componentes y recuperas ese uso al terminar un Descanso Corto o Largo; también puedes lanzarlo con espacios de conjuro del nivel adecuado. Característica de lanzamiento: INT, SAB o CAR (a tu elección al obtener la dote). Siberys Dragonmark Spells (conjuro: Marca sugerida si quieres asociarlo a una): Animal Shapes: Handling; Control Weather: Storm; Demiplane: Making; Heroes' Feast: Hospitality; Maze: Warding; Mind Blank: Sentinel; Plane Shift: Passage; Project Image: Shadow; Regenerate: Healing; Symbol: Scribing; Teleport: Finding; True Seeing: Detection." },
  { n:"Greater Aberrant Mark [EFotA 2024]", tipo:"General (EFotA 2024)", a:"O", d:"Req. Nv.4+, dote Aberrant Dragonmark. +1 CON (máx. 20). Fortaleza Mejorada (Improved Fortitude): al usar Fortaleza Aberrante de tu dote Aberrant Dragonmark, puedes tirar 1d6 en lugar de 1d4; además recuperas el uso de Fortaleza Aberrante al terminar un Descanso Corto o Largo. Marca de Inspiración (Mark of Inspiration): al lanzar un truco, puedes tirar 1 o 2 de tus Dados de Golpe sin gastar; ganas PG temporales iguales al resultado total + tu mod. CON, y una criatura de tu elección a 30 pies de ti (que no seas tú) sufre daño de Fuerza igual al resultado total; esos dados quedan gastados. Puedes usar este beneficio tantas veces como tu bonificador de competencia y recuperas todos los usos al terminar un Descanso Largo." },
  { n:"Greater Mark of Detection [EFotA 2024]", tipo:"General (EFotA 2024)", a:"A", d:"Req. Nv.4+, dote Mark of Detection. +1 a una característica (máx. 20). Intuición Mejorada (Improved Intuition): al usar el beneficio Intuición Deductiva (Deductive Intuition) de tu dote Mark of Detection, puedes tirar 1d6 en lugar de 1d4. Detección Compartida (Shared Detection): al usar el beneficio Detección Mágica (Magical Detection) de tu dote Mark of Detection para lanzar See Invisibility sin espacio de conjuro, puedes elegir una criatura que veas a 30 pies de ti; esa criatura también obtiene los efectos del conjuro mientras dure." },
  { n:"Greater Mark of Finding [EFotA 2024]", tipo:"General (EFotA 2024)", a:"B", d:"Req. Nv.4+, dote Mark of Finding. +1 a una característica (máx. 20). Intuición Mejorada (Improved Intuition): al usar el beneficio Intuición del Cazador (Hunter's Intuition) de tu dote Mark of Finding, puedes tirar 1d6 en lugar de 1d4. Búsqueda Mejorada (Improved Finding): al usar el beneficio Magia del Buscador (Finder's Magic) de tu dote Mark of Finding para lanzar Hunter's Mark sin espacio de conjuro, el alcance del conjuro se duplica y puedes modificarlo para que el objetivo no pueda beneficiarse de la condición Invisible mientras dure." },
  { n:"Greater Mark of Handling [EFotA 2024]", tipo:"General (EFotA 2024)", a:"AR", d:"Req. Nv.4+, dote Mark of Handling. +1 a una característica (máx. 20). Intuición Mejorada (Improved Intuition): al usar el beneficio Intuición Salvaje (Wild Intuition) de tu dote Mark of Handling, puedes tirar 1d6 en lugar de 1d4. Manejo Mejorado (Improved Handling): mientras vas montado, justo después de impactar con una tirada de ataque cuerpo a cuerpo a un objetivo a 5 pies de tu montura, ésta puede usar su Reacción para moverse hasta su Velocidad o para realizar la acción Atacar con un solo ataque (a tu elección). Someter Animal (Subdue Animal): con la acción de Magia, ejerces mando sobre una Bestia o Monstruosidad que veas a 30 pies de ti; el objetivo debe superar una salvación de SAB (CD 8 + tu mod. SAB + tu bonificador de competencia) o queda Asustado hasta el inicio de tu siguiente turno. Puedes usar este beneficio tantas veces como tu bonificador de competencia y recuperas todos los usos al terminar un Descanso Largo." },
  { n:"Greater Mark of Healing [EFotA 2024]", tipo:"General (EFotA 2024)", a:"A", d:"Req. Nv.4+, dote Mark of Healing. +1 a una característica (máx. 20). Intuición Mejorada (Improved Intuition): al usar el beneficio Intuición Médica (Medical Intuition) de tu dote Mark of Healing, puedes tirar 1d6 en lugar de 1d4. Sanación Mejorada (Improved Healing): ahora puedes usar el beneficio Toque Sanador (Healing Touch) de tu dote Mark of Healing para lanzar Cure Wounds sin espacio de conjuro tantas veces como tu bonificador de competencia, y recuperas todos los usos al terminar un Descanso Largo. Además, al lanzar Cure Wounds y tirar dados para determinar los PG recuperados, puedes tratar cualquier 1 o 2 como un 3." },
  { n:"Greater Mark of Hospitality [EFotA 2024]", tipo:"General (EFotA 2024)", a:"A", d:"Req. Nv.4+, dote Mark of Hospitality. +1 a una característica (máx. 20). Intuición Mejorada (Improved Intuition): al usar el beneficio Siempre Hospitalario (Ever Hospitable) de tu dote Mark of Hospitality, puedes tirar 1d6 en lugar de 1d4. Hospitalidad Mejorada (Improved Hospitality): al lanzar Purify Food and Drink, puedes modificar el conjuro para que, en lugar de su efecto normal, cada criatura de tu elección a 30 pies de ti quede revitalizada: su nivel de Agotamiento se reduce en 1 y gana PG temporales iguales a tu bonificador de competencia + tu mod. INT, SAB o CAR (a tu elección al obtener esta dote). Una vez modificado el conjuro así, no puedes volver a hacerlo hasta que termines un Descanso Largo." },
  { n:"Greater Mark of Making [EFotA 2024]", tipo:"General (EFotA 2024)", a:"B", d:"Req. Nv.4+, dote Mark of Making. +1 a una característica (máx. 20). Intuición Mejorada (Improved Intuition): al usar el beneficio Intuición del Artesano (Artisan's Intuition) de tu dote Mark of Making, puedes tirar 1d6 en lugar de 1d4. Creación Mejorada (Improved Making): al usar el beneficio Forjador de Conjuros (Spellsmith) de tu dote Mark of Making para lanzar Magic Weapon sin espacio de conjuro, lanzas el conjuro como su versión de nivel 3." },
  { n:"Greater Mark of Passage [EFotA 2024]", tipo:"General (EFotA 2024)", a:"B", d:"Req. Nv.4+, dote Mark of Passage. +1 a una característica (máx. 20). Intuición Mejorada (Improved Intuition): al usar el beneficio Movimiento Intuitivo (Intuitive Motion) de tu dote Mark of Passage, puedes tirar 1d6 en lugar de 1d4. Pasaje Mejorado (Improved Passage): al usar el beneficio Pasaje Mágico (Magical Passage) de tu dote Mark of Passage para lanzar Misty Step sin espacio de conjuro, antes de teletransportarte puedes elegir hasta 2 criaturas voluntarias que veas a 30 pies de ti; cada objetivo puede entonces usar su Reacción para teletransportarse también hasta 30 pies a un espacio desocupado que vea." },
  { n:"Greater Mark of Scribing [EFotA 2024]", tipo:"General (EFotA 2024)", a:"A", d:"Req. Nv.4+, dote Mark of Scribing. +1 a una característica (máx. 20). Intuición Mejorada (Improved Intuition): al usar el beneficio Escriba Dotado (Gifted Scribe) de tu dote Mark of Scribing, puedes tirar 1d6 en lugar de 1d4. Escritura Inspirada (Inspired Scribing): al lanzar Comprehend Languages, puedes modificar el conjuro para que abarque hasta 3 criaturas voluntarias que veas a 30 pies de ti; cada criatura elegida también obtiene los efectos del conjuro mientras dure. Además, mientras dure el conjuro, tú y las criaturas elegidas podéis comunicaros telepáticamente entre vosotros a 1 milla o menos. Una vez modificado el conjuro así, no puedes volver a hacerlo hasta que termines un Descanso Largo." },
  { n:"Greater Mark of Sentinel [EFotA 2024]", tipo:"General (EFotA 2024)", a:"R", d:"Req. Nv.4+, dote Mark of Sentinel. +1 a una característica (máx. 20). Intuición Mejorada (Improved Intuition): al usar el beneficio Intuición del Centinela (Sentinel's Intuition) de tu dote Mark of Sentinel, puedes tirar 1d6 en lugar de 1d4. Centinela Mejorado (Improved Sentinel): al usar el beneficio Guardián Vigilante (Vigilant Guardian) de tu dote Mark of Sentinel, también puedes realizar un ataque con un arma o un Ataque Desarmado como parte de esa misma Reacción." },
  { n:"Greater Mark of Shadow [EFotA 2024]", tipo:"General (EFotA 2024)", a:"A", d:"Req. Nv.4+, dote Mark of Shadow. +1 a una característica (máx. 20). Intuición Mejorada (Improved Intuition): al usar el beneficio Intuición Astuta (Cunning Intuition) de tu dote Mark of Shadow, puedes tirar 1d6 en lugar de 1d4. Sombra Mejorada (Improved Shadow): al usar el beneficio Moldear Sombras (Shape Shadows) de tu dote Mark of Shadow para lanzar Invisibility sin espacio de conjuro, lanzas el conjuro como su versión de nivel 3." },
  { n:"Greater Mark of Storm [EFotA 2024]", tipo:"General (EFotA 2024)", a:"A", d:"Req. Nv.4+, dote Mark of Storm. +1 a una característica (máx. 20). Intuición Mejorada (Improved Intuition): al usar el beneficio Intuición del Artífice del Viento (Windwright's Intuition) de tu dote Mark of Storm, puedes tirar 1d6 en lugar de 1d4. Tormenta Mejorada (Improved Storm): al usar el beneficio Magia de la Tormenta (Storm Magic) de tu dote Mark of Storm para lanzar Gust of Wind sin espacio de conjuro, también obtienes una Velocidad de vuelo de 60 pies mientras dure el conjuro." },
  { n:"Greater Mark of Warding [EFotA 2024]", tipo:"General (EFotA 2024)", a:"R", d:"Req. Nv.4+, dote Mark of Warding. +1 a una característica (máx. 20). Intuición Mejorada (Improved Intuition): al usar el beneficio Intuición del Custodio (Warder's Intuition) de tu dote Mark of Warding, puedes tirar 1d6 en lugar de 1d4. Protección Mejorada (Improved Warding): cuando una criatura hace una tirada de ataque contra ti o contra una criatura que veas a 30 pies de ti, puedes usar tu Reacción para imponer Desventaja a esa tirada. Puedes usar este beneficio tantas veces como tu bonificador de competencia y recuperas todos los usos al terminar un Descanso Largo." },
  { n:"Mark of Detection [EFotA 2024]", tipo:"Dragonmark (EFotA 2024)", a:"A", d:"Req. Campaña de Eberron; no tener otra dote Dragonmark. Intuición Deductiva (Deductive Intuition): al hacer una Prueba de INT (Investigación) o de SAB (Perspicacia), puedes tirar 1d4 y sumarlo a la prueba. Detección Mágica (Magical Detection): siempre tienes preparados Detect Magic y Detect Poison and Disease; puedes lanzar cada uno 1 vez sin espacio de conjuro y recuperas ese uso al terminar un Descanso Largo; también puedes lanzarlos con espacios de conjuro del nivel adecuado. Característica de lanzamiento: INT, SAB o CAR (a tu elección al obtener la dote). Al llegar al nivel de personaje 3, también tienes siempre preparado See Invisibility y puedes lanzarlo del mismo modo. Conjuros de la Marca (Spells of the Mark): si tienes el rasgo Lanzamiento de Conjuros o Magia de Pacto, los conjuros de la tabla Mark of Detection Spells se añaden a la lista de conjuros de ese rasgo (nivel de conjuro: conjuros) 1: Detect Evil and Good, Identify; 2: Detect Thoughts, Find Traps; 3: Clairvoyance, Nondetection; 4: Arcane Eye, Divination; 5: Legend Lore." },
  { n:"Mark of Finding [EFotA 2024]", tipo:"Dragonmark (EFotA 2024)", a:"AB", d:"Req. Campaña de Eberron; no tener otra dote Dragonmark. Intuición del Cazador (Hunter's Intuition): al hacer una Prueba de SAB (Percepción o Supervivencia), puedes tirar 1d4 y sumarlo a la prueba. Magia del Buscador (Finder's Magic): siempre tienes preparado Hunter's Mark; puedes lanzarlo 1 vez sin espacio de conjuro y recuperas ese uso al terminar un Descanso Largo; también puedes lanzarlo con espacios de conjuro del nivel adecuado. Característica de lanzamiento: INT, SAB o CAR (a tu elección al obtener la dote). Al llegar al nivel de personaje 3, también tienes siempre preparado Locate Object y puedes lanzarlo del mismo modo. Conjuros de la Marca (Spells of the Mark): si tienes el rasgo Lanzamiento de Conjuros o Magia de Pacto, los conjuros de la tabla Mark of Finding Spells se añaden a la lista de conjuros de ese rasgo (nivel de conjuro: conjuros) 1: Faerie Fire, Longstrider; 2: Locate Animals or Plants, Mind Spike; 3: Clairvoyance, Speak with Plants; 4: Divination, Locate Creature; 5: Commune with Nature." },
  { n:"Mark of Handling [EFotA 2024]", tipo:"Dragonmark (EFotA 2024)", a:"A", d:"Req. Campaña de Eberron; no tener otra dote Dragonmark. Intuición Salvaje (Wild Intuition): al hacer una Prueba de INT (Naturaleza) o de SAB (Trato con Animales), puedes tirar 1d4 y sumarlo a la prueba. Conexión Primigenia (Primal Connection): siempre tienes preparados Animal Friendship y Speak with Animals; puedes lanzar cada uno 1 vez sin espacio de conjuro y recuperas ese uso al terminar un Descanso Largo; también puedes lanzarlos con espacios de conjuro. Característica de lanzamiento: INT, SAB o CAR (a tu elección al obtener la dote). Conexiones Monstruosas (Monstrous Connections): al llegar al nivel de personaje 3, puedes elegir como objetivo a una Monstruosidad con Animal Friendship o Speak with Animals si su puntuación de INT es 3 o menos. Conjuros de la Marca (Spells of the Mark): si tienes el rasgo Lanzamiento de Conjuros o Magia de Pacto, los conjuros de la tabla Mark of Handling Spells se añaden a la lista de conjuros de ese rasgo (nivel de conjuro: conjuros) 1: Command, Find Familiar; 2: Beast Sense, Calm Emotions; 3: Beacon of Hope, Conjure Animals; 4: Aura of Life, Dominate Beast; 5: Awaken." },
  { n:"Mark of Healing [EFotA 2024]", tipo:"Dragonmark (EFotA 2024)", a:"AB", d:"Req. Campaña de Eberron; no tener otra dote Dragonmark. Intuición Médica (Medical Intuition): al hacer una Prueba de SAB (Medicina) o una Prueba de característica con un Herbalism Kit, puedes tirar 1d4 y sumarlo a la prueba. Toque Sanador (Healing Touch): siempre tienes preparado Cure Wounds; puedes lanzarlo 1 vez sin espacio de conjuro y recuperas ese uso al terminar un Descanso Largo; también puedes lanzarlo con espacios de conjuro del nivel adecuado. Característica de lanzamiento: INT, SAB o CAR (a tu elección al obtener la dote). Al llegar al nivel de personaje 3, también tienes siempre preparado Lesser Restoration y puedes lanzarlo del mismo modo. Conjuros de la Marca (Spells of the Mark): si tienes el rasgo Lanzamiento de Conjuros o Magia de Pacto, los conjuros de la tabla Mark of Healing Spells se añaden a la lista de conjuros de ese rasgo (nivel de conjuro: conjuros) 1: False Life, Healing Word; 2: Arcane Vigor, Prayer of Healing; 3: Aura of Vitality, Mass Healing Word; 4: Aura of Life, Aura of Purity; 5: Greater Restoration." },
  { n:"Mark of Hospitality [EFotA 2024]", tipo:"Dragonmark (EFotA 2024)", a:"A", d:"Req. Campaña de Eberron; no tener otra dote Dragonmark. Siempre Hospitalario (Ever Hospitable): al hacer una Prueba de CAR (Persuasión) o una Prueba de característica con Brewer's Supplies o Cook's Utensils, puedes tirar 1d4 y sumarlo a la prueba. Magia del Posadero (Innkeeper's Magic): siempre tienes preparados Purify Food and Drink y Unseen Servant; puedes lanzar cada uno 1 vez sin espacio de conjuro y recuperas ese uso al terminar un Descanso Largo; también puedes lanzarlos con espacios de conjuro del nivel adecuado. Característica de lanzamiento: INT, SAB o CAR (a tu elección al obtener la dote). Al llegar al nivel de personaje 3, también tienes siempre preparado Calm Emotions y puedes lanzarlo del mismo modo. Conjuros de la Marca (Spells of the Mark): si tienes el rasgo Lanzamiento de Conjuros o Magia de Pacto, los conjuros de la tabla Mark of Hospitality Spells se añaden a la lista de conjuros de ese rasgo (nivel de conjuro: conjuros) 1: Goodberry, Sleep; 2: Aid, Enhance Ability; 3: Create Food and Water, Leomund's Tiny Hut; 4: Aura of Purity, Mordenkainen's Private Sanctum; 5: Hallow." },
  { n:"Mark of Making [EFotA 2024]", tipo:"Dragonmark (EFotA 2024)", a:"B", d:"Req. Campaña de Eberron; no tener otra dote Dragonmark. Intuición del Artesano (Artisan's Intuition): al hacer una Prueba de INT (Arcana) o una Prueba de característica con Artisan's Tools, puedes tirar 1d4 y sumarlo a la prueba. Forjador de Conjuros (Spellsmith): conoces el truco Mending; además siempre tienes preparado Magic Weapon; puedes lanzarlo 1 vez sin espacio de conjuro y recuperas ese uso al terminar un Descanso Largo; también puedes lanzarlo con espacios de conjuro. Característica de lanzamiento: INT, SAB o CAR (a tu elección al obtener la dote). Conjuros de la Marca (Spells of the Mark): si tienes el rasgo Lanzamiento de Conjuros o Magia de Pacto, los conjuros de la tabla Mark of Making Spells se añaden a la lista de conjuros de ese rasgo (nivel de conjuro: conjuros) 1: Identify, Tenser's Floating Disk; 2: Continual Flame, Spiritual Weapon; 3: Conjure Barrage, Elemental Weapon; 4: Fabricate, Stone Shape; 5: Creation." },
  { n:"Mark of Passage [EFotA 2024]", tipo:"Dragonmark (EFotA 2024)", a:"B", d:"Req. Campaña de Eberron; no tener otra dote Dragonmark. Rapidez del Mensajero (Courier's Speed): tu Velocidad aumenta 5 pies. Movimiento Intuitivo (Intuitive Motion): al hacer una Prueba de FUE (Atletismo) o de DES (Acrobacias), puedes tirar 1d4 y sumarlo a la prueba. Pasaje Mágico (Magical Passage): siempre tienes preparado Misty Step; puedes lanzarlo 1 vez sin espacio de conjuro y recuperas ese uso al terminar un Descanso Largo; también puedes lanzarlo con espacios de conjuro. Característica de lanzamiento: INT, SAB o CAR (a tu elección al obtener la dote). Conjuros de la Marca (Spells of the Mark): si tienes el rasgo Lanzamiento de Conjuros o Magia de Pacto, los conjuros de la tabla Mark of Passage Spells se añaden a la lista de conjuros de ese rasgo (nivel de conjuro: conjuros) 1: Expeditious Retreat, Jump; 2: Find Steed, Pass without Trace; 3: Blink, Phantom Steed; 4: Dimension Door, Freedom of Movement; 5: Teleportation Circle." },
  { n:"Mark of Scribing [EFotA 2024]", tipo:"Dragonmark (EFotA 2024)", a:"A", d:"Req. Campaña de Eberron; no tener otra dote Dragonmark. Escriba Dotado (Gifted Scribe): al hacer una Prueba de INT (Historia) o una Prueba de característica con Calligrapher's Supplies, puedes tirar 1d4 y sumarlo a la prueba. Perspicacia del Escriba (Scribe's Insight): conoces el truco Message; además siempre tienes preparado Comprehend Languages; puedes lanzarlo 1 vez sin espacio de conjuro y recuperas ese uso al terminar un Descanso Largo; también puedes lanzarlo con espacios de conjuro del nivel adecuado. Característica de lanzamiento: INT, SAB o CAR (a tu elección al obtener la dote). Al llegar al nivel de personaje 3, también tienes siempre preparado Magic Mouth y puedes lanzarlo del mismo modo. Conjuros de la Marca (Spells of the Mark): si tienes el rasgo Lanzamiento de Conjuros o Magia de Pacto, los conjuros de la tabla Mark of Scribing Spells se añaden a la lista de conjuros de ese rasgo (nivel de conjuro: conjuros) 1: Command, Illusory Script; 2: Animal Messenger, Silence; 3: Sending, Tongues; 4: Arcane Eye, Confusion; 5: Dream." },
  { n:"Mark of Sentinel [EFotA 2024]", tipo:"Dragonmark (EFotA 2024)", a:"R", d:"Req. Campaña de Eberron; no tener otra dote Dragonmark. Intuición del Centinela (Sentinel's Intuition): al hacer una Prueba de SAB (Perspicacia o Percepción), puedes tirar 1d4 y sumarlo a la prueba. Escudo del Guardián (Guardian's Shield): siempre tienes preparado Shield; puedes lanzarlo 1 vez sin espacio de conjuro y recuperas ese uso al terminar un Descanso Largo; también puedes lanzarlo con espacios de conjuro. Característica de lanzamiento: INT, SAB o CAR (a tu elección al obtener la dote). Guardián Vigilante (Vigilant Guardian): cuando una criatura que veas a 5 pies de ti es impactada por una tirada de ataque, puedes usar tu Reacción para intercambiar tu posición con la de esa criatura, y el ataque te impacta a ti en su lugar. Puedes usar este rasgo tantas veces como tu bonificador de competencia y recuperas todos los usos al terminar un Descanso Largo. Conjuros de la Marca (Spells of the Mark): si tienes el rasgo Lanzamiento de Conjuros o Magia de Pacto, los conjuros de la tabla Mark of Sentinel Spells se añaden a la lista de conjuros de ese rasgo (nivel de conjuro: conjuros) 1: Compelled Duel, Shield of Faith; 2: Warding Bond, Zone of Truth; 3: Counterspell, Protection from Energy; 4: Death Ward, Guardian of Faith; 5: Bigby's Hand." },
  { n:"Mark of Shadow [EFotA 2024]", tipo:"Dragonmark (EFotA 2024)", a:"A", d:"Req. Campaña de Eberron; no tener otra dote Dragonmark. Intuición Astuta (Cunning Intuition): al hacer una Prueba de DES (Sigilo) o de CAR (Interpretación), puedes tirar 1d4 y sumarlo a la prueba. Moldear Sombras (Shape Shadows): conoces el truco Minor Illusion; además siempre tienes preparado Invisibility; puedes lanzarlo 1 vez sin espacio de conjuro y recuperas ese uso al terminar un Descanso Largo; también puedes lanzarlo con espacios de conjuro del nivel adecuado. Característica de lanzamiento: INT, SAB o CAR (a tu elección al obtener la dote). Conjuros de la Marca (Spells of the Mark): si tienes el rasgo Lanzamiento de Conjuros o Magia de Pacto, los conjuros de la tabla Mark of Shadow Spells se añaden a la lista de conjuros de ese rasgo (nivel de conjuro: conjuros) 1: Disguise Self, Silent Image; 2: Darkness, Pass without Trace; 3: Clairvoyance, Major Image; 4: Greater Invisibility, Hallucinatory Terrain; 5: Mislead." },
  { n:"Mark of Storm [EFotA 2024]", tipo:"Dragonmark (EFotA 2024)", a:"A", d:"Req. Campaña de Eberron; no tener otra dote Dragonmark. Intuición del Artífice del Viento (Windwright's Intuition): al hacer una Prueba de DES (Acrobacias) o una Prueba de característica con Navigator's Tools, puedes tirar 1d4 y sumarlo a la prueba. Don de la Tormenta (Storm's Boon): tienes Resistencia al daño de Relámpago. Magia de la Tormenta (Storm Magic): conoces el truco Thunderclap. Al llegar al nivel de personaje 3, también tienes siempre preparado Gust of Wind; puedes lanzarlo 1 vez sin espacio de conjuro y recuperas ese uso al terminar un Descanso Largo; también puedes lanzarlo con espacios de conjuro del nivel adecuado. Característica de lanzamiento: INT, SAB o CAR (a tu elección al obtener la dote). Conjuros de la Marca (Spells of the Mark): si tienes el rasgo Lanzamiento de Conjuros o Magia de Pacto, los conjuros de la tabla Mark of Storm Spells se añaden a la lista de conjuros de ese rasgo (nivel de conjuro: conjuros) 1: Feather Fall, Fog Cloud; 2: Levitate, Shatter; 3: Sleet Storm, Wind Wall; 4: Conjure Minor Elementals, Control Water; 5: Conjure Elemental." },
  { n:"Mark of Warding [EFotA 2024]", tipo:"Dragonmark (EFotA 2024)", a:"A", d:"Req. Campaña de Eberron; no tener otra dote Dragonmark. Intuición del Custodio (Warder's Intuition): al hacer una Prueba de INT (Investigación) o una Prueba de característica con Thieves' Tools, puedes tirar 1d4 y sumarlo a la prueba. Protecciones y Sellos (Wards and Seals): siempre tienes preparados Alarm y Mage Armor; puedes lanzar cada uno 1 vez sin espacio de conjuro y recuperas ese uso al terminar un Descanso Largo; también puedes lanzarlos con espacios de conjuro del nivel adecuado. Característica de lanzamiento: INT, SAB o CAR (a tu elección al obtener la dote). Al llegar al nivel de personaje 3, también tienes siempre preparado Arcane Lock y puedes lanzarlo del mismo modo. Conjuros de la Marca (Spells of the Mark): si tienes el rasgo Lanzamiento de Conjuros o Magia de Pacto, los conjuros de la tabla Mark of Warding Spells se añaden a la lista de conjuros de ese rasgo (nivel de conjuro: conjuros) 1: Armor of Agathys, Sanctuary; 2: Knock, Nystul's Magic Aura; 3: Glyph of Warding, Magic Circle; 4: Leomund's Secret Chest, Mordenkainen's Faithful Hound; 5: Antilife Shell." },
  { n:"Potent Dragonmark [EFotA 2024]", tipo:"General (EFotA 2024)", a:"O", d:"Req. Nv.4+, dote de categoría Dragonmark. +1 a la característica de lanzamiento de tu dote Dragonmark (máx. 20). Preparación de Dragonmark (Dragonmark Preparation): siempre tienes preparados los conjuros de tu lista de Conjuros de la Marca (si tienes). Lanzamiento de Dragonmark (Dragonmark Spellcasting): tienes 1 espacio de conjuro extra para lanzar los conjuros que concede tu dote Dragonmark; su nivel es la mitad de tu nivel (redondeando hacia arriba), hasta un máximo de nivel 5; recuperas el espacio gastado al terminar un Descanso Corto o Largo. Solo puedes usar este espacio para lanzar un conjuro que tengas preparado por tu dote Dragonmark o por el beneficio Preparación de Dragonmark de esta dote." },

  /* ═══════════════════════════════════════════
     FORGOTTEN REALMS: HEROES OF FAERÛN (HoF, 2024)
  ═══════════════════════════════════════════ */
  { n:"Boon of Bloodshed [HoF 2024]", tipo:"Boon Épico (HoF 2024)", d:"Req. Nv.19+. +1 a una característica (máx. 30). Fortuna del Asesino (Killer's Fortune): cuando un enemigo que veas llega a 0 PG, tienes Ventaja en la siguiente tirada de ataque que hagas antes del final de tu siguiente turno. Poder del Dolor (Power from Pain): una vez por turno, al hacer una tirada de ataque estando Ensangrentado (mitad de PG o menos), infliges al objetivo daño extra igual a tu bonificador de competencia, del mismo tipo que el del ataque." },
  { n:"Boon of Bountiful Health [HoF 2024]", tipo:"Boon Épico (HoF 2024)", d:"Req. Nv.19+. +1 a una característica (máx. 30). Salud Aumentada (Augmented Health): cuando ganas PG temporales, ganas 5 más. Recuperación Superior (Superior Recuperation): cuando gastas Dados de Golpe para recuperar PG, puedes usar en su lugar el valor máximo posible de cada dado." },
  { n:"Boon of Communication [HoF 2024]", tipo:"Boon Épico (HoF 2024)", d:"Req. Nv.19+. +1 INT, SAB o CAR (máx. 30). Orador Astuto (Cunning Speaker): no tienes Desventaja en las Pruebas de característica para influir en criaturas Hostiles. Intérprete Dotado (Gifted Interpreter): entiendes el significado literal de cualquier idioma que oigas o veas en señas, y de cualquier idioma escrito que veas. Comunicación Mental (Mental Communication): tienes telepatía con un alcance de 120 pies." },
  { n:"Boon of Desperate Resilience [HoF 2024]", tipo:"Boon Épico (HoF 2024)", d:"Req. Nv.19+. +1 FUE o CON (máx. 30). Defensa de Cuerpo y Mente (Defense of Body and Mind): mientras estás Ensangrentado (mitad de PG o menos), tienes Resistencia a todos los tipos de daño excepto el de Fuerza." },
  { n:"Boon of Exquisite Radiance [HoF 2024]", tipo:"Boon Épico (HoF 2024)", a:"O", d:"Req. Nv.19+. +1 a una característica (máx. 30). Descanso Eterno (Eternal Rest): las criaturas que reduzcas a 0 PG no pueden convertirse en No Muertos. Radiancia Poderosa (Powerful Radiance): al hacer una tirada de daño que inflige daño Radiante, puedes usar en su lugar el valor máximo posible de cada dado de daño; no puedes volver a usarlo hasta que termines un Descanso Largo." },
  { n:"Boon of Fluid Forms [HoF 2024]", tipo:"Boon Épico (HoF 2024)", a:"A", d:"Req. Nv.19+. +1 INT, SAB o CAR (máx. 30). Cambiaformas (Shapechanger): con la acción de Magia te transformas en una Bestia, Humanoide o Monstruosidad con CR máximo 10 y ganas PG temporales iguales a los PG de esa forma. Dura 1 hora y termina antes si te quedas sin PG temporales o si usas la acción de Magia para volver a tu forma real. Tus estadísticas pasan a ser las del bloque de la forma elegida, pero conservas tu tipo de criatura, alineamiento, personalidad, puntuaciones de INT, SAB y CAR, PG, Dados de Golpe, competencias y capacidad de comunicarte; si tienes Lanzamiento de Conjuros o Magia de Pacto, también lo conservas. Al transformarte decides si tu equipo cae al suelo o se adapta en tamaño y forma a la nueva forma mientras la mantengas. No puedes volver a usarlo hasta que termines un Descanso Largo. Transformación Resistente (Hardy Transformation): cuando ganas PG temporales al transformarte, aumentas esa cantidad en 20." },
  { n:"Boon of Fortune's Favor [HoF 2024]", tipo:"Boon Épico (HoF 2024)", a:"O", d:"Req. Nv.19+. +1 a una característica (máx. 30). Repetir Salvación (Saving Throw Reroll): cuando fallas una tirada de salvación, puedes repetirla y debes usar la nueva tirada; no puedes volver a usarlo hasta el inicio de tu siguiente turno." },
  { n:"Boon of Poison Mastery [HoF 2024]", tipo:"Boon Épico (HoF 2024)", d:"Req. Nv.19+. +1 a una característica (máx. 30). Antitóxico (Antitoxic): tienes Inmunidad al daño de Veneno y a la condición Envenenado. Envenenador Perfecto (Perfect Poisoner): una vez por turno, al tirar dados para determinar el daño de Veneno que una criatura sufre por tu ataque, conjuro o rasgo, puedes usar en su lugar el valor máximo posible de cada dado." },
  { n:"Boon of Revelry [HoF 2024]", tipo:"Boon Épico (HoF 2024)", a:"A", d:"Req. Nv.19+. +1 INT, SAB o CAR (máx. 30). Inspirar el Baile (Inspire Dance): siempre tienes preparado Otto's Irresistible Dance. Puedes lanzarlo 1 vez sin espacio de conjuro (recuperas ese uso al terminar un Descanso Largo) y también con cualquier espacio de conjuro del nivel adecuado. Al lanzarlo no requiere componentes y recibir daño no rompe tu Concentración en él. Cantar a Voz en Grito (Sing Out): mientras una criatura que falló su salvación contra tu Otto's Irresistible Dance tenga la condición Hechizado por ese conjuro, no puede lanzar conjuros con componentes Verbales y, si puede cantar, canta tonterías deliciosas." },
  { n:"Boon of Terror [HoF 2024]", tipo:"Boon Épico (HoF 2024)", a:"R", d:"Req. Nv.19+. +1 CAR (máx. 30). Intrépido (Fearless): tienes Inmunidad a la condición Asustado. ¡Huid, Necios! (Flee, Fools!): cuando una criatura con la condición Asustado empieza su turno a 60 pies de ti, puedes usar tu Reacción para avivar su terror, si la ves y no está tras Cobertura Total; debe superar una salvación de SAB (CD 8 + mod. CAR + bonificador de competencia) o gastar su turno alejándose de ti por el medio más rápido disponible. No puedes volver a usarlo hasta que termines un Descanso Corto o Largo. Intimidante (Intimidating): ganas Competencia en Intimidación si no la tienes, y además Pericia en Intimidación." },
  { n:"Boon of the Bright Sun [HoF 2024]", tipo:"Boon Épico (HoF 2024)", a:"B", d:"Req. Nv.19+. +1 CON, SAB o CAR (máx. 30). Presencia Diurna (Daylight Presence): como Acción Adicional irradias una Emanación de 30 pies de Luz Brillante que es luz solar. Si parte de su área se solapa con un área de Oscuridad creada por un conjuro, ese conjuro es disipado. La Emanación dura hasta que la despidas (sin acción), mueras o tengas la condición Incapacitado. Luz Fortificante (Fortifying Light): con tu Presencia Diurna activa, al inicio de cada uno de tus turnos tú y los aliados que veas dentro de ella ganáis 10 PG temporales." },
  { n:"Boon of the Furious Storm [HoF 2024]", tipo:"Boon Épico (HoF 2024)", d:"Req. Nv.19+, rasgo Lanzamiento de Conjuros o Magia de Pacto. +1 INT, SAB o CAR (máx. 30). Ojo de la Tormenta (Eye of the Storm): tienes Resistencia al daño de Relámpago y de Trueno; mientras estés Ensangrentado (mitad de PG o menos), tienes Inmunidad a ese daño. Fuerza de la Tormenta (Storm's Strength): las criaturas tienen Desventaja en las tiradas de salvación contra tus conjuros que infligen daño de Relámpago o de Trueno." },
  { n:"Boon of the Soul Drinker [HoF 2024]", tipo:"Boon Épico (HoF 2024)", a:"R", d:"Req. Nv.19+. +1 a una característica (máx. 30). Resistencia de Tumba (Grave Resistance): tienes Resistencia al daño de Frío y Necrótico. Succionar Vida (Siphon Life): cuando un enemigo a 120 pies de ti llega a 0 PG, puedes usar tu Reacción para recuperar 50 PG. No puedes volver a usarlo hasta que termines un Descanso Corto o Largo." },
  { n:"Cold Caster [HoF 2024]", tipo:"General (HoF 2024)", d:"Req. Nv.4+. +1 INT, SAB o CAR (máx. 20). Truco (Cantrip): aprendes el truco Ray of Frost; si ya lo conoces, aprendes otro truco de Mago a tu elección. La característica de lanzamiento de ese conjuro es la que aumentaste con esta dote. Congelación (Frostbite): una vez por turno, al impactar a una criatura con una tirada de ataque e infligir daño de Frío, puedes anular temporalmente sus defensas: la criatura resta 1d4 de la siguiente tirada de salvación que haga antes del final de tu siguiente turno." },
  { n:"Cult of the Dragon Initiate [HoF 2024]", tipo:"Origen (HoF 2024)", a:"A", d:"Lengua del Dragón (Dragon's Tongue): conoces el idioma Dracónico; si ya lo conoces al elegir la dote, aprendes en su lugar un idioma a tu elección de las tablas de idiomas del Player's Handbook o del Capítulo 2 de Heroes of Faerûn. Terror del Dragón (Dragon's Terror): con la acción de Magia infundes terror a una criatura que veas a 30 pies de ti; debe superar una salvación de SAB (CD 8 + mod. SAB + bonificador de competencia) o tener la condición Asustado hasta el final de tu siguiente turno. Si supera la salvación, o cuando el efecto termina, el objetivo es inmune a este efecto durante 24 horas. Inspirado por el Miedo (Inspired by Fear): cuando haces que una criatura tenga la condición Asustado y eres la fuente de su miedo, puedes ganar Inspiración Heroica si no la tienes; no puedes volver a usarlo hasta que termines un Descanso Corto o Largo." },
  { n:"Dragonscarred [HoF 2024]", tipo:"General (HoF 2024)", a:"B", d:"Req. Nv.4+, dote Cult of the Dragon Initiate. +1 CON o CAR (máx. 20). Resistencia al Daño (Damage Resistance): al obtener esta dote eliges Ácido, Frío, Fuego, Relámpago o Veneno; tienes Resistencia a ese tipo de daño. Poder Aterrador (Fearsome Power): cuando infliges daño a una criatura como parte de la acción Atacar o de Magia en tu turno, puedes usar este turno el beneficio Terror del Dragón (Dragon's Terror) de la dote Cult of the Dragon Initiate como Acción Adicional." },
  { n:"Emerald Enclave Fledgling [HoF 2024]", tipo:"Origen (HoF 2024)", a:"A", d:"Speak with Animals: siempre tienes preparado este conjuro y puedes lanzarlo con cualquier espacio de conjuro que tengas; INT, SAB o CAR es tu característica de lanzamiento para él (se elige al obtener la dote). Si lo lanzas como Ritual, su duración es de 8 horas. Trabajo en Equipo (Tag Team): cuando realizas la acción Ayudar, puedes intercambiar tu posición con un aliado voluntario a 5 pies de ti como parte de esa misma acción; este movimiento no provoca Ataques de Oportunidad. No puedes usarlo si el aliado tiene la condición Incapacitado." },

  /* ═══════════════════════════════════════════
     FORGOTTEN REALMS: HEROES OF FAERÛN (HoF, 2024)
  ═══════════════════════════════════════════ */
  { n:"Enclave Magic [HoF 2024]", tipo:"General (HoF 2024)", a:"A", d:"Req. Nv.4+, dote Emerald Enclave Fledgling. +1 INT, SAB o CAR (máx. 20). Amigo de los Animales (Friend to Animals): Ventaja en las Pruebas de característica al realizar la acción Influir con Bestias. Dos Corazones, una Sola Mente (Two Hearts, One Mind): siempre tienes preparado Beast Sense. Puedes lanzarlo 1 vez sin espacio de conjuro y recuperas ese uso al terminar un Descanso Largo; al lanzarlo así con este beneficio no requiere Concentración. También puedes lanzarlo con espacios de conjuro del nivel adecuado. Característica de lanzamiento del conjuro: la que aumentaste con esta dote." },
  { n:"Fairy Trickster [HoF 2024]", tipo:"General (HoF 2024)", a:"O", d:"Req. Nv.4+. +1 DES o CAR (máx. 20). Senda Feérica (Faerie Trod Trotter): al realizar la acción Retirarse en tu turno, el Terreno Difícil no te cuesta movimiento adicional el resto de ese turno. Golpe Desconcertante (Flustering Strike): al impactar a una criatura con una tirada de ataque, puedes intentar desconcertarla: el objetivo debe superar una salvación de SAB (CD 8 + mod. de la característica aumentada con esta dote + bonificador de competencia) o tiene Desventaja en las tiradas de salvación hasta el final de tu siguiente turno. Puedes usar este beneficio tantas veces como tu bonificador de competencia y recuperas todos los usos al terminar un Descanso Largo." },
  { n:"Genie Magic [HoF 2024]", tipo:"General (HoF 2024)", a:"A", d:"Req. Nv.4+. +1 INT, SAB o CAR (máx. 20). Magia del Deseo (Wish Magic): con la acción de Magia lanzas un conjuro de nivel 1 a tu elección de la lista de Hechicero que tenga tiempo de lanzamiento de una acción. Una vez usado, no puedes volver a hacerlo hasta que termines un Descanso Largo. Característica de lanzamiento del conjuro: la que aumentaste con esta dote. Al llegar a nivel 11 de personaje, el conjuro se lanza como si usaras un espacio de nivel 2; al llegar a nivel 17, como si usaras un espacio de nivel 3." },
  { n:"Harper Agent [HoF 2024]", tipo:"Origen (HoF 2024)", d:"Jerga de Ladrones (Thieves' Cant): conoces la Jerga de Ladrones. Entrenamiento con Instrumentos (Instrument Training): ganas competencia con un Instrumento Musical a tu elección. Melodía Distractora (Distracting Melody): al realizar la acción Ayudar para asistir la tirada de ataque de un aliado, el enemigo al que distraes puede estar a 30 pies de ti en lugar de a 5 pies, siempre que pueda verte u oírte." },
  { n:"Harper Teamwork [HoF 2024]", tipo:"General (HoF 2024)", d:"Req. Nv.4+, dote Harper Agent. +1 DES o CAR (máx. 20). Juego de Palabras Marchitante (Withering Wordplay): al realizar la acción Ayudar para asistir la tirada de ataque de un aliado contra un enemigo, ese enemigo también tiene Desventaja en la primera tirada de salvación que haga antes del inicio de tu siguiente turno. Voluntad Inspiradora (Inspiring Willpower): si superas una tirada de salvación para terminar la condición Asustado o Paralizado en ti, puedes elegir a un aliado que veas a 30 pies de ti y tenga esa misma condición: la condición termina de inmediato para ese aliado." },
  { n:"Lordly Resolve [HoF 2024]", tipo:"General (HoF 2024)", a:"B", d:"Req. Nv.4+, dote Lords' Alliance Agent. +1 FUE o CAR (máx. 20). Portaestandarte (Standard Bearer): como Acción Adicional, eliges hasta 3 criaturas a 60 pies de ti que puedan verte. Cada objetivo puede usar de inmediato su Reacción para levantarse y terminar la condición Tumbado, siempre que su Velocidad no sea 0. Además, refuerzas su determinación durante 1 minuto o hasta que tengas la condición Incapacitado. Mientras está reforzado, un objetivo no puede ser poseído ni ganar las condiciones Hechizado o Asustado; si ya está poseído, Hechizado o Asustado, tiene Ventaja en cualquier nueva tirada de salvación contra el efecto correspondiente. Una vez usado, no puedes volver a hacerlo hasta que termines un Descanso Largo." },
  { n:"Lords' Alliance Agent [HoF 2024]", tipo:"Origen (HoF 2024)", d:"Golpe Inspirador (Inspiring Strike): una vez por turno, al causar un Impacto Crítico a una criatura, puedes elegir a un aliado a 30 pies de ti que pueda verte u oírte y no tenga Inspiración Heroica: ese aliado gana Inspiración Heroica. Reafirmar el Honor (Reassert Honor): cuando un enemigo que veas inflige daño a un aliado tuyo que está a 5 pies de ti, tienes Ventaja en tu siguiente tirada de ataque contra ese enemigo antes del final de tu siguiente turno." },
  { n:"Mythal Touched [HoF 2024]", tipo:"General (HoF 2024)", a:"R", d:"Req. Nv.4+. +1 INT, SAB o CAR (máx. 20). Protección del Mythal (Mythal Ward): si un ataque de conjuro te impacta o fallas una tirada de salvación contra un conjuro, puedes usar una Reacción para tirar en la tabla Magia Tocada por el Mythal (Mythal-Touched Magic) y crear un efecto mágico. Si el efecto requiere una tirada de salvación, la CD es 8 + el modificador de la característica aumentada con esta dote + tu bonificador de competencia. Puedes usar este beneficio tantas veces como tu bonificador de competencia y recuperas todos los usos al terminar un Descanso Largo. Tabla d20 (el «lanzador» es quien lanzó el conjuro desencadenante) — 1-2: tú y cada criatura a 15 pies de ti hacéis una salvación de DES; sufrís daño de Fuerza igual a 1d8 por el nivel del conjuro desencadenante si falláis, o la mitad si superáis. 3-7: tú y el lanzador formáis un vínculo telepático durante 1 hora. 8-10: la gravedad se invierte durante 1 minuto en un Cilindro de 15 pies de radio y 60 pies de altura centrado en ti, como el conjuro Reverse Gravity. 11-13: tú y el lanzador hacéis una salvación de CON; si falla, la criatura tiene la condición Aturdido hasta el final de su siguiente turno. 14-17: ganas +2 a la CA durante 1 minuto, lo que puede hacer fallar al conjuro desencadenante si era un ataque de conjuro. 18-19: todo objeto inflamable y no mágico a 10 pies del lanzador que no lleve puesto ni porte otra criatura estalla en llamas, sufre 1d4 de daño de Fuego y arde. 20: el conjuro desencadenante se disipa sin efecto y se pierde la acción, Acción Adicional o Reacción usada para lanzarlo; si se lanzó con un espacio de conjuro, el espacio no se gasta." },
  { n:"Order's Resilience [HoF 2024]", tipo:"General (HoF 2024)", d:"Req. Nv.4+, dote Tyro of the Gauntlet. +1 FUE, SAB o CAR (máx. 20). Resurgir (Resurge): si tienes la condición Tumbado, puedes levantarte gastando solo 5 pies de movimiento. Más Fuertes Juntos (Stronger Together): si estás a 5 pies de un aliado que no tenga la condición Incapacitado, tú y ese aliado tenéis Ventaja en las tiradas de salvación de FUE. No puedes usar este beneficio mientras tengas la condición Incapacitado." },
  { n:"Purple Dragon Commandant [HoF 2024]", tipo:"General (HoF 2024)", a:"B", d:"Req. Nv.4+ y dote Purple Dragon Rook, o competencia con armas Marciales. +1 FUE o DES (máx. 20). Animar al Aliado (Encourage Ally): como Acción Adicional, alientas a un aliado que veas a 30 pies de ti: gana PG temporales iguales a 2d6 + el modificador de la característica aumentada con esta dote. Puedes usar esta Acción Adicional tantas veces como tu bonificador de competencia y recuperas todos los usos al terminar un Descanso Largo. Último Bastión (Last Stand): tienes Ventaja en las tiradas de ataque mientras estés Ensangrentado (mitad de PG o menos)." },
  { n:"Purple Dragon Rook [HoF 2024]", tipo:"Origen (HoF 2024)", a:"O", d:"Exhortar (Entreat): ganas competencia en una de estas habilidades a tu elección: Perspicacia, Interpretación o Persuasión. Grito de Aliento (Rallying Cry): al tirar Iniciativa sin tener la condición Incapacitado, puedes elegir a tantas criaturas que veas a 30 pies de ti como tu bonificador de competencia: esas criaturas ganan Inspiración Heroica. Una vez usado, no puedes volver a hacerlo hasta que termines un Descanso Largo." },
  { n:"Spellfire Adept [HoF 2024]", tipo:"General (HoF 2024)", a:"O", d:"Req. Nv.4+ y dote Spellfire Spark, o rasgo Lanzamiento de Conjuros o Magia de Pacto. +1 INT, SAB o CAR (máx. 20). Fuego de Conjuro Alimentado (Fueled Spellfire): una vez por turno, cuando un conjuro que lanzas inflige daño Radiante, puedes gastar hasta 2 Dados de Golpe, tirarlos y sumar el total a una de las tiradas de daño del conjuro. Fuego de Conjuro Abrasador (Searing Spellfire): tus tiradas de daño que infligen daño Radiante ignoran la Resistencia al daño Radiante." },
  { n:"Spellfire Spark [HoF 2024]", tipo:"Origen (HoF 2024)", a:"AB", d:"Absorción Mágica (Magic Absorption): una vez por turno, cuando sufres daño de un conjuro o efecto mágico, reduces el daño total sufrido en 1d4. No puedes usar este beneficio si tienes la condición Incapacitado. Llama de Fuego de Conjuro (Spellfire Flame): aprendes el truco Sacred Flame. INT, SAB o CAR es tu característica de lanzamiento para este truco (se elige al obtener la dote). También puedes lanzarlo como Acción Adicional tantas veces como tu bonificador de competencia, y recuperas todos los usos al terminar un Descanso Largo." },
  { n:"Street Justice [HoF 2024]", tipo:"General (HoF 2024)", d:"Req. Nv.4+. +1 FUE o DES (máx. 20). Llave de Cabeza (Headlock): tus aliados tienen Ventaja en las tiradas de ataque contra una criatura que tengas Agarrada. Nudo Firme (Sturdy Knot): al usar Chain, Manacles o Rope para inmovilizar a una criatura, suma tu bonificador de competencia a la CD para escapar o romper la Chain, Manacles o Rope. Charla Dura (Tough Talk): la actitud Hostil de una criatura no impone Desventaja a tus pruebas de CAR (Intimidación) para influir en ella." },
  { n:"Tyro of the Gauntlet [HoF 2024]", tipo:"Origen (HoF 2024)", a:"R", d:"Mantenerse Unidos (Stand as One): cuando un aliado a 5 pies de ti es sometido a un efecto que lo empujaría o tiraría de él, puedes usar una Reacción para evitar que lo empujen o tiren de él. Para recibir este beneficio, el aliado no puede tener la condición Incapacitado. Vigilante (Vigilant): al realizar la acción Preparar, la siguiente tirada de ataque contra ti antes del inicio de tu siguiente turno tiene Desventaja." },
  { n:"Zhentarim Ruffian [HoF 2024]", tipo:"Origen (HoF 2024)", a:"O", d:"Aprovechar la Apertura (Exploit Opening): al tirar el daño de un Ataque de Oportunidad, puedes tirar los dados de daño dos veces y usar cualquiera de las dos tiradas contra el objetivo. La Familia Primero (Family First): si tienes Inspiración Heroica al tirar Iniciativa, puedes gastarla para que tú y tus aliados tengáis Ventaja en esa tirada de Iniciativa." },
  { n:"Zhentarim Tactics [HoF 2024]", tipo:"General (HoF 2024)", a:"R", d:"Req. Nv.4+, dote Zhentarim Ruffian. +1 DES o CAR (máx. 20). Represalia (Retaliate): justo después de que una criatura a 5 pies de ti te impacte con un ataque cuerpo a cuerpo, puedes hacerle un Ataque de Oportunidad. Mercenario Versátil (Versatile Merc): al terminar un Descanso Largo, elige una habilidad en la que tengas competencia: tienes Pericia en ella hasta que termines tu siguiente Descanso Largo." },

  /* ═══════════════════════════════════════════
     EBERRON: RISING FROM THE LAST WAR (ERftLW, 2014)
  ═══════════════════════════════════════════ */
  { n:"Aberrant Dragonmark [ERftLW]", tipo:"General (ERftLW)", a:"O", d:"Req. ninguna otra Dragonmark. +1 CON (máx. 20). Has manifestado una Dragonmark aberrante; determina su aspecto y el defecto asociado. Aprendes 1 truco a tu elección de la lista de Hechicero y eliges 1 conjuro de nivel 1 de esa lista, que aprendes y puedes lanzar mediante tu marca; tras lanzarlo debes terminar un Descanso Corto o Largo para volver a lanzarlo con la marca. Característica de lanzamiento: CON. Al lanzar el conjuro de nivel 1 con la marca puedes gastar 1 Dado de Golpe y tirarlo: si sale par, ganas PG temporales iguales al resultado; si sale impar, una criatura aleatoria a 30 pies de ti (sin contarte) sufre daño de fuerza igual al resultado (si no hay otras criaturas en alcance, lo sufres tú). Defecto: además sufres un defecto aleatorio (tira 1d8): 1: tu marca es fuente de dolor físico constante; 2: tu marca te susurra, con un significado poco claro; 3: cuando estás estresado, la marca sisea de forma audible; 4: la piel alrededor de la marca está quemada, escamosa o marchita; 5: los animales se inquietan a tu alrededor; 6: cambias de humor cada vez que usas la marca; 7: tu aspecto cambia ligeramente cada vez que usas la marca; 8: tienes pesadillas horribles después de usar la marca. Opción del DM (Poderes Aberrantes Mayores, Greater Aberrant Powers): al alcanzar el Nv.10, el personaje tiene un 10 % de probabilidad de obtener un Boon Épico de las opciones del capítulo 7 de la Dungeon Master's Guide; si no lo obtiene, repite la tirada del 10 % cada vez que sube de nivel. Si lo obtiene, el DM lo elige o lo determina al azar; además el personaje pierde para siempre 1 Dado de Golpe y su máximo de PG se reduce en una tirada de ese dado + su mod. CON (reducción mínima de 1), algo que no se puede revertir por ningún medio." },
  { n:"Revenant Blade [ERftLW]", tipo:"General (ERftLW)", d:"Req. Elfo. +1 FUE o DES (máx. 20). Desciendes de un maestro de la cimitarra de doble hoja y parte de esa maestría ha pasado a ti. Mientras empuñas una Double-Bladed Scimitar con las dos manos, ganas un bonificador de +1 a la CA. Una Double-Bladed Scimitar tiene la propiedad Sutil (Finesse) cuando la empuñas." },

  /* ═══════════════════════════════════════════
     DRAGONLANCE: SHADOW OF THE DRAGON QUEEN (SotDQ)
  ═══════════════════════════════════════════ */
  { n:"Adept of the Black Robes [SotDQ]", tipo:"General (SotDQ)", a:"O", d:"Req. Nv.4+, dote Initiate of High Sorcery (Nuitari). Elegiste a la luna Nuitari para influir en tu magia y la Orden de las Túnicas Negras ha reconocido tu ambición y lealtad. Magia Ambiciosa (Ambitious Magic): aprendes 1 conjuro de nivel 2 a tu elección de la escuela de Encantamiento o Nigromancia; lo lanzas 1 vez sin espacio y debes terminar un Descanso Largo para volver a hacerlo así (también puedes lanzarlo con espacios de conjuro del nivel adecuado). Característica de lanzamiento: la elegida con Initiate of High Sorcery. Canalizar Vida (Life Channel): cuando una criatura que veas a 60 pies de ti falla una tirada de salvación contra un conjuro tuyo que inflige daño, puedes gastar tantos Dados de Golpe como el nivel del conjuro, tirarlos y sumarlos: el daño que sufre la criatura aumenta en ese total." },
  { n:"Adept of the Red Robes [SotDQ]", tipo:"General (SotDQ)", a:"O", d:"Req. Nv.4+, dote Initiate of High Sorcery (Lunitari). Elegiste a la luna Lunitari para influir en tu magia y la Orden de las Túnicas Rojas ha reconocido tu dedicación a mantener el equilibrio entre todas las cosas. Magia Perspicaz (Insightful Magic): aprendes 1 conjuro de nivel 2 a tu elección de la escuela de Ilusión o Transmutación; lo lanzas 1 vez sin espacio y debes terminar un Descanso Largo para volver a hacerlo así (también puedes lanzarlo con espacios de conjuro del nivel adecuado). Característica de lanzamiento: la elegida con Initiate of High Sorcery. Equilibrio Mágico (Magical Balance): al hacer una tirada de ataque o una Prueba de característica y sacar 9 o menos en el d20, puedes equilibrar el destino y tratar la tirada como un 10. Puedes hacerlo tantas veces como tu bonificador de competencia y recuperas todos los usos al terminar un Descanso Largo." },
  { n:"Adept of the White Robes [SotDQ]", tipo:"General (SotDQ)", a:"OR", d:"Req. Nv.4+, dote Initiate of High Sorcery (Solinari). Elegiste a la luna Solinari para influir en tu magia y la Orden de las Túnicas Blancas ha reconocido tu juramento de usar la magia para hacer del mundo un lugar mejor. Magia Protectora (Protective Magic): aprendes 1 conjuro de nivel 2 a tu elección de la escuela de Abjuración o Adivinación; lo lanzas 1 vez sin espacio y debes terminar un Descanso Largo para volver a hacerlo así (también puedes lanzarlo con espacios de conjuro del nivel adecuado). Característica de lanzamiento: la elegida con Initiate of High Sorcery. Resguardo Protector (Protective Ward): cuando tú o una criatura que veas a 30 pies de ti sufre daño, puedes usar tu Reacción para gastar un espacio de conjuro y tejer magia protectora en torno al objetivo: tira tantos d6 como el nivel del espacio gastado y reduce el daño que sufre el objetivo en el total obtenido + tu modificador de característica de lanzamiento." },
  { n:"Divinely Favored [SotDQ]", tipo:"General (SotDQ)", a:"O", d:"Req. Nv.4+, campaña Dragonlance. Un dios te ha elegido para portar una chispa de su poder. Aprendes 1 truco a tu elección de la lista de Clérigo, 1 conjuro de nivel 1 según tu alineamiento y el conjuro Augury. Conjuro de nivel 1 por alineamiento: Malvado: 1 conjuro de Brujo de nivel 1; Bueno: 1 conjuro de Clérigo de nivel 1; Neutral: 1 conjuro de Druida de nivel 1. Lanzas el conjuro de nivel 1 elegido y Augury sin espacio, y debes terminar un Descanso Largo para volver a hacerlo así (también puedes lanzarlos con espacios de conjuro del nivel adecuado). Característica de lanzamiento: INT, SAB o CAR (a elegir al obtener la dote). Además, puedes usar un símbolo sagrado como foco de lanzamiento de cualquier conjuro que lances y que use la característica elegida para esta dote." },
  { n:"Initiate of High Sorcery [SotDQ]", tipo:"General (SotDQ)", a:"O", d:"Req. campaña Dragonlance y Nv.1 de Hechicero, Nv.1 de Mago o trasfondo Mage of High Sorcery. Has recibido formación de magos afiliados a los Magos de la Alta Hechicería (Mages of High Sorcery). Eliges una de las tres lunas de Krynn para influir en tu magia (Nuitari, la luna negra; Lunitari, la roja; Solinari, la blanca): aprendes 1 truco a tu elección de la lista de Mago y 2 conjuros de nivel 1 según la luna elegida (tabla Lunar Spells). Nuitari: 2 entre Dissonant Whispers, False Life, Hex y Ray of Sickness. Lunitari: 2 entre Color Spray, Disguise Self, Feather Fall y Longstrider. Solinari: 2 entre Comprehend Languages, Detect Evil and Good, Protection from Evil and Good y Shield. Lanzas cada uno de los conjuros de nivel 1 elegidos 1 vez sin espacio y debes terminar un Descanso Largo para volver a hacerlo así (también puedes lanzarlos con cualquier espacio de conjuro que tengas). Característica de lanzamiento: INT, SAB o CAR (a elegir al obtener la dote)." },
  { n:"Knight of the Crown [SotDQ]", tipo:"General (SotDQ)", a:"B", d:"Req. Nv.4+, dote Squire of Solamnia. +1 FUE, DES o CON (máx. 20). Eres un Caballero de Solamnia de la Orden de la Corona, que ensalza la cooperación, la lealtad y la obediencia; destacas en el combate en grupo. Reunión de Mando (Commanding Rally): como Acción Adicional ordenas atacar a un aliado a 30 pies de ti; si el aliado puede verte u oírte, hace de inmediato 1 ataque con arma como Reacción y, si impacta, puede tirar 1d8 y sumarlo como bonificador a la tirada de daño. Puedes usar esta Acción Adicional tantas veces como tu bonificador de competencia y recuperas todos los usos al terminar un Descanso Largo. Pertenencia a las Órdenes de Caballería (Membership in Knightly Orders): un Caballero de Solamnia solo pertenece a una orden; la mayoría empieza en la Orden de la Corona y luego pasa a otras. Conservas lo aprendido en una orden aunque te unas a otra, y puedes cambiar de orden pero siempre mantienes las dotes de Caballero de Solamnia que hayas obtenido." },
  { n:"Knight of the Rose [SotDQ]", tipo:"General (SotDQ)", a:"B", d:"Req. Nv.4+, dote Squire of Solamnia. +1 CON, SAB o CAR (máx. 20). Eres un Caballero de Solamnia de la Orden de la Rosa, conocida por su liderazgo, justicia y sabiduría. Reunión Alentadora (Bolstering Rally): como Acción Adicional animas a una criatura que veas a 30 pies de ti (puedes elegirte a ti mismo); si el objetivo puede verte u oírte, gana PG temporales iguales a 1d8 + tu bonificador de competencia + el modificador de la característica aumentada con esta dote. Puedes usar esta Acción Adicional tantas veces como tu bonificador de competencia y recuperas todos los usos al terminar un Descanso Largo. Pertenencia a las Órdenes de Caballería (Membership in Knightly Orders): un Caballero de Solamnia solo pertenece a una orden; la mayoría empieza en la Orden de la Corona y luego pasa a otras. Conservas lo aprendido en una orden aunque te unas a otra, y puedes cambiar de orden pero siempre mantienes las dotes de Caballero de Solamnia que hayas obtenido." },
  { n:"Knight of the Sword [SotDQ]", tipo:"General (SotDQ)", a:"O", d:"Req. Nv.4+, dote Squire of Solamnia. +1 INT, SAB o CAR (máx. 20). Eres un Caballero de Solamnia de la Orden de la Espada, dedicada al heroísmo y al valor. Golpe Desmoralizador (Demoralizing Strike): una vez por turno, al impactar a una criatura con una tirada de ataque con arma, puedes intentar asustarla: el objetivo hace una salvación de SAB (CD 8 + bonificador de competencia + modificador de la característica aumentada con esta dote). Si falla, queda Asustado de ti hasta el final de tu siguiente turno; si la supera, tiene Desventaja en la siguiente tirada de ataque que haga antes del final de su siguiente turno. Puedes usar este beneficio tantas veces como tu bonificador de competencia y recuperas todos los usos al terminar un Descanso Largo. Pertenencia a las Órdenes de Caballería (Membership in Knightly Orders): un Caballero de Solamnia solo pertenece a una orden; la mayoría empieza en la Orden de la Corona y luego pasa a otras. Conservas lo aprendido en una orden aunque te unas a otra, y puedes cambiar de orden pero siempre mantienes las dotes de Caballero de Solamnia que hayas obtenido." },
  { n:"Squire of Solamnia [SotDQ]", tipo:"General (SotDQ)", a:"O", d:"Req. campaña Dragonlance y Nv.1 de Guerrero, Nv.1 de Paladín o trasfondo Knight of Solamnia. Tu formación en las costumbres de los Caballeros de Solamnia te otorga: Montar (Mount Up): montar o desmontar te cuesta solo 5 pies de movimiento. Golpe Preciso (Precise Strike): una vez por turno, al hacer una tirada de ataque con arma contra una criatura, puedes darle Ventaja; si el ataque impacta, tiras 1d8 y lo sumas como bonificador a la tirada de daño. Puedes usar este beneficio tantas veces como tu bonificador de competencia, pero solo se gasta un uso si el ataque impacta; recuperas todos los usos al terminar un Descanso Largo. Pertenencia a las Órdenes de Caballería (Membership in Knightly Orders): un Caballero de Solamnia solo pertenece a una orden; la mayoría empieza en la Orden de la Corona y luego pasa a otras. Conservas lo aprendido en una orden aunque te unas a otra, y puedes cambiar de orden pero siempre mantienes las dotes de Caballero de Solamnia que hayas obtenido." },

  /* ═══════════════════════════════════════════
     SIGIL AND THE OUTLANDS (SatO)
  ═══════════════════════════════════════════ */
  { n:"Agent of Order [SatO]", tipo:"General (SatO)", a:"O", d:"Req. Nv.4+, dote Scion of the Outer Planes (Plano Exterior Legal). +1 a una característica (máx. 20). Canalizas las fuerzas cósmicas del orden. Golpe de Estasis (Stasis Strike): una vez por turno, al dañar a una criatura que veas a 60 pies de ti, puedes infligirle 1d8 de daño de fuerza adicional; además, la criatura hace una salvación de SAB (CD 8 + bonificador de competencia + mod. de la característica de lanzamiento elegida para Scion of the Outer Planes) mientras unas ataduras espectrales (cadenas u otro símbolo de estasis) intentan atraparla. Si la supera, escapa; si falla, queda Restringida hasta el inicio de tu siguiente turno. Puedes usar este beneficio tantas veces como tu bonificador de competencia y recuperas todos los usos al terminar un Descanso Largo." },
  { n:"Baleful Scion [SatO]", tipo:"General (SatO)", a:"O", d:"Req. Nv.4+, dote Scion of the Outer Planes (Plano Exterior Maligno). +1 a una característica (máx. 20). Canalizas las fuerzas cósmicas del mal. Presa de la Avaricia (Grasp of Avarice): una vez por turno, al dañar a una criatura que veas a 60 pies de ti, puedes infligirle además daño necrótico igual a 1d6 + tu bonificador de competencia y recuperas PG iguales al daño necrótico infligido. Puedes usar este beneficio tantas veces como tu bonificador de competencia y recuperas todos los usos al terminar un Descanso Largo." },
  { n:"Cohort of Chaos [SatO]", tipo:"General (SatO)", a:"O", d:"Req. Nv.4+, dote Scion of the Outer Planes (Plano Exterior Caótico). +1 a una característica (máx. 20). Canalizas las fuerzas cósmicas del caos. Destello Caótico (Chaotic Flare): al sacar un 1 o un 20 en una tirada de ataque o de salvación, la magia del caos fluye por ti: tira 1d4 en la tabla de Destellos Caóticos. El destello dura hasta el final de tu siguiente turno y no puede producirse otro hasta que el primero termine. Tabla (1d4): 1: Furia de Batalla (Battle Fury), una criatura a tu elección que veas se llena de furia temeraria: tiene Ventaja en las tiradas de ataque y Desventaja en las Pruebas de característica; 2: Campo de Disrupción (Disruption Field), ondas de energía te rodean: toda criatura que empiece su turno a 5 pies de ti, o que entre en esa zona por primera vez en un turno, sufre 1d8 de daño de fuerza; 3: Desatado (Unbound), cuando te mueves puedes usar parte o toda tu Velocidad caminando para teletransportarte una vez, con tu equipo, hasta una distancia igual a la usada, a un espacio desocupado que veas; 4: Vientos Lastimeros (Wailing Winds), vientos arremolinados en una esfera de 15 pies de radio centrada en ti: tú y las demás criaturas de esa zona tenéis Desventaja en las tiradas de salvación de SAB." },
  { n:"Outlands Envoy [SatO]", tipo:"General (SatO)", a:"AB", d:"Req. Nv.4+, dote Scion of the Outer Planes (The Outlands). +1 a una característica (máx. 20). Has pasado mucho tiempo en Sigil o en las Outlands, la encrucijada del multiverso, y estar impregnado de energías planares convergentes te otorga: Emisario de la Encrucijada (Crossroads Emissary): aprendes Misty Step y Tongues; lanzas cada uno 1 vez sin espacio y debes terminar un Descanso Largo para volver a hacerlo así. Al lanzar Tongues con esta dote no necesitas componentes materiales. También puedes lanzarlos con espacios de conjuro del nivel adecuado. Característica de lanzamiento: la elegida al obtener Scion of the Outer Planes." },
  { n:"Planar Wanderer [SatO]", tipo:"General (SatO)", a:"A", d:"Req. Nv.4+, dote Scion of the Outer Planes. Puedes recurrir a las fuerzas del multiverso para sobrevivir a sus extremos cósmicos y recorrer sus reinos infinitos. Adaptación Planar (Planar Adaptation): al terminar un Descanso Largo, ganas Resistencia al daño de ácido, frío o fuego (a tu elección) hasta que termines tu siguiente Descanso Largo. Forzador de Portales (Portal Cracker): abres portales sin llave de portal. Con tu acción te concentras en un portal que conozcas a 5 pies de ti y haces una Prueba de INT (Arcana) CD 20. Si fallas, sufres 3d8 de daño psíquico y no puedes usar este beneficio en ese portal hasta que termines un Descanso Largo. Si tienes éxito, fuerzas el portal a abrirse o cerrarse durante 1 hora; durante ese tiempo el portal no responde a su llave de portal, salvo que una criatura que use la llave supere una Prueba de INT (Arcana) CD 20 como acción. Sentido de Portales (Portal Sense): conoces la dirección del último portal planar que usaste mientras tú y el portal estéis en el mismo plano de existencia; además, con una acción detectas la ubicación de cualquier portal a 30 pies de ti que no esté tras Cobertura Total. Tras detectar un portal con esta acción, no puedes volver a usarla hasta que termines un Descanso Largo." },
  { n:"Righteous Heritor [SatO]", tipo:"General (SatO)", a:"R", d:"Req. Nv.4+, dote Scion of the Outer Planes (Plano Exterior Bueno). +1 a una característica (máx. 20). Canalizas las fuerzas cósmicas del bien. Aliviar el Dolor (Soothe Pain): cuando tú o una criatura a 30 pies de ti sufre daño, puedes usar tu Reacción para reducir ese daño en 1d10 + tu bonificador de competencia. Puedes usar este beneficio tantas veces como tu bonificador de competencia y recuperas todos los usos al terminar un Descanso Largo." },
  { n:"Scion of the Outer Planes [SatO]", tipo:"General (SatO)", d:"Req. campaña Planescape. Tu conexión con un Plano Exterior te infunde la energía de ese lugar. Eliges un tipo de plano de la tabla Planar Infusion: tu elección te da Resistencia a un tipo de daño y la capacidad de lanzar un truco, según la tabla. Lanzas ese truco sin componentes materiales; tu característica de lanzamiento para él es INT, SAB o CAR (a elegir al obtener la dote). Tabla (plano: Resistencia, truco): Plano Exterior Caótico: Resistencia a veneno, Minor Illusion; Plano Exterior Maligno: Resistencia a necrótico, Chill Touch; Plano Exterior Bueno: Resistencia a radiante, Sacred Flame; Plano Exterior Legal: Resistencia a fuerza, Guidance; The Outlands: Resistencia a psíquico, Mage Hand." },

  /* ═══════════════════════════════════════════
     LORWYN: FIRST LIGHT (LFL, 2024)
  ═══════════════════════════════════════════ */
  { n:"Child of the Sun [LFL 2024]", tipo:"Origen (LFL 2024)", a:"A", d:"Ojos de Eirdu (Eyes of Eirdu): tú y los aliados a 10 pies de ti tenéis Ventaja en las tiradas de salvación para evitar o terminar la condición Cegado. Faerie Fire: aprendes el conjuro Faerie Fire; INT, SAB o CAR es tu característica de lanzamiento para él (a elegir al obtener la dote). Lo lanzas 1 vez sin espacio y recuperas ese uso al terminar un Descanso Largo; también puedes lanzarlo con espacios de conjuro. Al lanzarlo sin espacio con este beneficio, sufrir daño no rompe tu Concentración en él." },
  { n:"Shadowmoor Hexer [LFL 2024]", tipo:"Origen (LFL 2024)", a:"B", d:"Hex: siempre tienes preparado el conjuro Hex; INT, SAB o CAR es tu característica de lanzamiento para él (a elegir al obtener la dote). Lo lanzas 1 vez sin espacio y recuperas ese uso al terminar un Descanso Largo; también puedes lanzarlo con espacios de conjuro. Magia de Maldición (Curse Magic): cuando una criatura que has maldecido con Hex te impacta con una tirada de ataque, sufre daño Psíquico igual a tu bonificador de competencia; una criatura sufre este daño solo una vez por turno." },

  /* ═══════════════════════════════════════════
     PLANE SHIFT: KALADESH (PSK)
  ═══════════════════════════════════════════ */
  { n:"Quicksmithing [PSK]", tipo:"General (PSK)", a:"O", d:"Req. INT 13+. Dominas el arte de la invención, mejora y apaño sobre la marcha: con tiempo y suficiente suministro de aether creas efectos mágicos inmediatos y de corta duración similares a conjuros. Al elegir esta dote dominas 2 efectos mágicos, cada uno de los cuales reproduce el efecto de un conjuro de nivel 1 con la etiqueta Ritual (de la lista de cualquier clase); tu característica de lanzamiento para ellos es INT. Si encuentras un esquema de quicksmithing o estudias con otro quicksmith, puedes añadir otro conjuro a tus efectos dominados: su nivel no puede ser superior a la mitad de tu nivel (redondeando hacia arriba) y debe tener la etiqueta Ritual; dominarlo tarda 2 horas por nivel del conjuro y cuesta 50 po por nivel (el coste representa el aether que usas al experimentar con el efecto). Además, tienes Competencia con Herramientas de Artesano (quicksmith's tools). Con esas herramientas puedes gastar 1 hora y 10 po de materiales para construir un dispositivo de relojería Diminuto (CA 5, 1 PG), que deja de funcionar a las 24 horas salvo que dediques 1 hora a repararlo; con tu acción puedes desmontarlo y recuperar los materiales usados. Puedes tener hasta 3 de estos dispositivos activos a la vez. Al crear un dispositivo eliges una opción: Juguete de Relojería (Clockwork Toy): un animal, monstruo o persona de relojería (rana, ratón, pájaro, dragón, soldado...) que, colocado en el suelo, se mueve 5 pies en una dirección aleatoria en cada uno de tus turnos y hace ruidos acordes a lo que representa. Encendedor (Fire Starter): produce una llama en miniatura con la que encender una vela, antorcha u hoguera; usarlo requiere tu acción. Caja de Música (Music Box): al abrirla toca una única canción a volumen moderado; se detiene al terminar la canción o al cerrarla." },
  { n:"Servo Crafting [PSK]", tipo:"General (PSK)", a:"O", d:"Req. INT 13+. Eres hábil creando servos, constructos diminutos que funcionan como asistentes personales. Puedes lanzar Find Familiar como ritual y crear un servo como tu familiar en lugar de un animal (sus estadísticas aparecen en la sección Artifact Creatures del documento Plane Shift: Kaladesh); en todo lo demás, un familiar servo funciona como describe Find Familiar. Puedes comunicarte telepáticamente con tu servo y percibir a través de sus sentidos mientras estéis en el mismo plano de existencia; además puedes hablar a través de él con tu propia voz. Además, al realizar la acción Atacar, puedes renunciar a uno de tus ataques para que tu servo haga un ataque propio." },

  /* ═══════════════════════════════════════════
     MORDENKAINEN’S TOME OF FOES (MTF, 2014)
  ═══════════════════════════════════════════ */
  { n:"Svirfneblin Magic [MTF]", tipo:"General (MTF)", a:"A", d:"Req. Gnomo (gnomo de las profundidades). Has heredado la capacidad de lanzamiento innato de tus ancestros: lanzas Nondetection sobre ti a voluntad, sin componente material. También lanzas una vez cada uno de estos conjuros: Blindness/Deafness, Blur y Disguise Self; recuperas esos usos al terminar un Descanso Largo. Característica de lanzamiento: INT; los lanzas en su nivel más bajo posible." },

  /* ═══════════════════════════════════════════
     PLANE SHIFT: IXALAN (PSX)
  ═══════════════════════════════════════════ */
  { n:"Vampiric Exultation [PSX]", tipo:"General (PSX)", a:"A", d:"Req. Vampiro (Ixalan). Con tu acción puedes transformar la mitad inferior de tu cuerpo en un vapor negro como la tinta que te permite flotar en el aire. Mientras estás transformado, tienes Velocidad de vuelo 30 pies. Puedes mantener esta forma hasta 10 minutos. Tras usarla, no puedes volver a hacerlo hasta que termines un Descanso Corto o Largo." },

  /* ═══════════════════════════════════════════
     STRIXHAVEN: A CURRICULUM OF CHAOS (SCC)
  ═══════════════════════════════════════════ */
  { n:"Strixhaven Mascot [SCC]", tipo:"General (SCC)", a:"A", d:"Req. Nv.4+, dote Strixhaven Initiate. Has aprendido a invocar a una mascota de Strixhaven que te ayuda. Puedes lanzar Find Familiar como ritual; tu familiar puede adoptar la forma de la mascota asociada al colegio que elegiste con Strixhaven Initiate: mascota estatua espiritual (Lorehold), elemental artístico (Prismari), fractal (Quandrix), inkling (Silverquill) o pest (Witherbloom). Cuando realizas la acción Atacar en tu turno, puedes renunciar a un ataque para que tu mascota familiar haga un ataque propio con su Reacción. Si tu mascota familiar está a 60 pies de ti, puedes teletransportarte con una acción, intercambiando tu posición con la del familiar; si el espacio de destino es demasiado pequeño para ti, la teletransportación falla y se pierde. Tras teletransportarte así, no puedes volver a hacerlo hasta que termines un Descanso Largo, salvo que gastes un espacio de conjuro de nivel 2 o superior para repetirlo." },

  /* ═══════════════════════════════════════════
     PLAYER’S HANDBOOK 2024 (PHB 2024)
  ═══════════════════════════════════════════ */
  { n:"Blessed Warrior [PHB 2024]", tipo:"Estilo de Combate", d:"Req. al obtener el rasgo Estilo de Lucha del Paladín (Nv.2). Aprendes 2 trucos de Clérigo a tu elección (se recomiendan Guidance y Sacred Flame). Los trucos elegidos cuentan como conjuros de Paladín para ti y CAR es tu característica de lanzamiento para ellos. Cada vez que ganas un nivel de Paladín, puedes sustituir uno de estos trucos por otro truco de Clérigo." },
  { n:"Druidic Warrior [PHB 2024]", tipo:"Estilo de Combate", d:"Req. al obtener el rasgo Estilo de Lucha del Explorador (Nv.2). Aprendes 2 trucos de Druida a tu elección (se recomiendan Guidance y Starry Wisp). Los trucos elegidos cuentan como conjuros de Explorador para ti y SAB es tu característica de lanzamiento para ellos. Cada vez que ganas un nivel de Explorador, puedes sustituir uno de estos trucos por otro truco de Druida." },

  /* ═══════════════════════════════════════════
     RAVENLOFT: THE HORRORS WITHIN (THW, 2024)
  ═══════════════════════════════════════════ */
  { n:"Aberrant Anatomy [THW 2024]", tipo:"Dark Gift (THW 2024)", d:"Req. Campaña Ravenloft. Sin Respiración (Breathless): puedes contener la respiración 1 hora. Percepción Extrasensorial (Extrasensory Perception): ganas Competencia en Percepción si no la tenías y además ganas Pericia en esa habilidad; también tienes Vista Ciega con alcance de 15 pies. Carne Retorcida (Warping Flesh): justo después de hacer una Prueba de d20 y sacar un 1 en el d20, la influencia aberrante que infecta tu cuerpo se desata y te arrebata el control de tu carne: haces una salvación de CON (CD 13 + tu bonificador de competencia); si fallas, quedas Aturdido hasta el final de tu siguiente turno." },
  { n:"Echoing Soul [THW 2024]", tipo:"Dark Gift (THW 2024)", d:"Req. Campaña Ravenloft. Destreza Canalizada (Channeled Prowess): ganas Competencia en 2 habilidades a tu elección; además eliges 1 habilidad en la que tengas Competencia y ganas Pericia en ella, y puedes cambiar esa elección cada vez que termines un Descanso Largo. Lenguas Innatas (Inherent Tongues): conoces 1 idioma adicional a tu elección, de las tablas de idiomas del Player's Handbook. Ecos Intrusivos (Intrusive Echoes): justo después de hacer una Prueba de d20 y sacar un 1 en el d20, los recuerdos y sensaciones de la otra vida de tu alma amenazan con abrumarte: haces una salvación de CON (CD 13 + tu bonificador de competencia); si fallas, quedas Incapacitado hasta el final de tu siguiente turno y, mientras lo estés así, tu Velocidad se reduce a la mitad." },
  { n:"Gathered Whispers [THW 2024]", tipo:"Dark Gift (THW 2024)", a:"AR", d:"Req. Campaña Ravenloft. Susurros de Espíritus (Spirit Whispers): aprendes el truco Message y puedes lanzarlo sin componentes materiales. Además, siempre tienes preparado Augury: puedes lanzarlo sin espacio de conjuro ni componentes, pero debes terminar un Descanso Largo antes de volver a lanzarlo así; también puedes lanzarlo con tus espacios de conjuro. Tu característica de lanzamiento para este beneficio es INT, SAB o CAR (a elección al obtener la dote). Grito Sobrenatural (Unearthly Scream): cuando te impacta una tirada de ataque, puedes usar tu Reacción para canalizar a tus espíritus en un grito protector y sobrenatural y sumar tu bonificador de competencia a tu CA contra ese ataque, pudiendo hacerlo fallar. Usos = tu bonificador de competencia; recuperas todos los usos gastados al terminar un Descanso Largo. Voces del Más Allá (Voices from Beyond): justo después de hacer una Prueba de d20 y sacar un 1 en el d20, las voces que te acechan suben a un volumen espectral: haces una salvación de SAB (CD 13 + tu bonificador de competencia); si fallas, quedas Ensordecido hasta el final de tu siguiente turno. Mientras estés Ensordecido, tienes Desventaja en las Pruebas de característica y en las tiradas de ataque." },
  { n:"Living Shadow [THW 2024]", tipo:"Dark Gift (THW 2024)", a:"AO", d:"Req. Campaña Ravenloft. Sombra Aferradora (Grasping Shadow): aprendes el truco Mage Hand y puedes lanzarlo sin componentes. Tu característica de lanzamiento para este conjuro es INT, SAB o CAR (a elección al obtener la dote). Golpe Alargado (Lengthened Strike): cuando haces una tirada de ataque cuerpo a cuerpo como parte de la acción Atacar o de la acción de Magia en tu turno, puedes aumentar 10 pies tu alcance en ese ataque, pues tu sombra se estira para ayudarte. Usos = tu bonificador de competencia; recuperas todos los usos gastados al terminar un Descanso Largo. Voluntad Ominosa (Ominous Will): justo después de hacer una Prueba de d20 y sacar un 1 en el d20, tu sombra intenta imponer su voluntad: haces una salvación de SAB (CD 13 + tu bonificador de competencia); si fallas, quedas Incapacitado hasta el inicio de tu siguiente turno y, en ese momento, tiras en la tabla Voluntad de la Sombra (Shadow's Will) para saber qué haces durante ese turno. Voluntad de la Sombra (1d8): 1: no realizas acción ni Acción Adicional y gastas todo tu movimiento en moverte; tira 1d4 para la dirección (1 norte, 2 este, 3 sur, 4 oeste); 2-6: no te mueves ni usas Acción Adicional y realizas la acción Atacar para hacer un ataque cuerpo a cuerpo contra una criatura al azar a tu alcance, y si no hay ninguna, no realizas ninguna acción; 7-8: quedas Tumbado y tu turno termina." },
  { n:"Mist Walker [THW 2024]", tipo:"Dark Gift (THW 2024)", a:"R", d:"Req. Campaña Ravenloft. Viajero de Dominios (Domain Traveler): cuando entras en las Brumas con la intención de llegar a un dominio concreto, se te trata como si poseyeras un talismán de las Brumas (Mist talisman) sintonizado con ese dominio. Para usarlo debes conocer el nombre del dominio de destino, pero no hace falta haberlo visitado antes; no te permite saltarte las fronteras de dominios cerradas por voluntad de un Señor Oscuro (Darklord). Paso de Bruma (Mist Walk): cuando sufres daño o fallas una tirada de salvación para evitar o terminar la condición Agarrado o Apresado, puedes usar tu Reacción para teletransportarte hasta 15 pies a un espacio libre que veas. Usos = tu bonificador de competencia; recuperas todos los usos gastados al terminar un Descanso Largo. Raíces Envenenadas (Poisoned Roots): cuando terminas un Descanso Largo, el mundo en un radio de 10 millas a tu alrededor se convierte en un sifón que drena tu vitalidad. Cada vez que termines un Descanso Corto en esa zona, haces una salvación de CON (CD 13 + tu bonificador de competencia); si fallas, no obtienes ningún beneficio de terminar ese descanso." },
  { n:"Second Skin [THW 2024]", tipo:"Dark Gift (THW 2024)", a:"A", d:"Req. Campaña Ravenloft. Forma Alterna (Alternate Form): siempre tienes preparado Alter Self. Puedes lanzarlo sin espacio de conjuro ni componentes, pero debes terminar un Descanso Largo antes de volver a lanzarlo así; también puedes lanzarlo con tus espacios de conjuro del nivel apropiado. Tu característica de lanzamiento para este conjuro es INT, SAB o CAR (a elección al obtener la dote). Cuando lanzas Alter Self sin espacio de conjuro con este rasgo, no requiere Concentración. Cambio Involuntario (Involuntary Change): ciertas circunstancias pueden provocar tu transformación sin quererlo; al elegir la dote, tiras en la tabla Catalizador del Cambio (Change Catalyst) para saber qué la desencadena. Tras experimentar el catalizador, al inicio de tu siguiente turno haces una salvación de CAR (CD 13 + tu bonificador de competencia); si fallas, lanzas de inmediato Alter Self sin espacio de conjuro mediante Forma Alterna. Si ya has gastado el uso de ese rasgo, quedas en cambio Aturdido hasta el inicio de tu siguiente turno. Catalizador del Cambio (1d6): 1: ver una fase concreta de la luna; 2: oler cierto tipo de flor; 3: oír campanas de templo; 4: oír una melodía concreta; 5: tocar plata pura con la piel desnuda; 6: ver a alguien que se parece a un individuo concreto." },
  { n:"Sharp Eye [THW 2024]", tipo:"Origen (THW 2024)", a:"O", d:"Al realizar la acción Buscar o Estudiar, puedes darte Ventaja en cualquier Prueba de característica hecha como parte de esa acción. Usos = tu bonificador de competencia; recuperas todos los usos gastados al terminar un Descanso Largo. Si la prueba falla, no se gasta el uso." },
  { n:"Survivor [THW 2024]", tipo:"Origen (THW 2024)", a:"R", d:"Hipervigilancia (Hypervigilance): cada vez que tiras iniciativa, puedes repetir el d20 si el resultado es 9 o menos; debes usar la nueva tirada. Templar el Ánimo (Steel Yourself): cuando fallas una tirada de salvación para evitar o terminar la condición Hechizado o Asustado, puedes usar tu Reacción para sumar a la tirada un bonificador igual a tu bonificador de competencia, pudiendo convertir el fallo en éxito. Tras usar esta Reacción, no puedes volver a hacerlo hasta terminar un Descanso Largo." },
  { n:"Symbiotic Being [THW 2024]", tipo:"Dark Gift (THW 2024)", a:"R", d:"Req. Campaña Ravenloft. Existencia Entrelazada (Entwined Existence): el simbionte no puede ser objetivo de nada. Si mueres, tu simbionte muere también; si vuelves a la vida, tu simbionte revive contigo. Segunda Mente (Second Mind): ganas Competencia en una de estas habilidades: Arcana, Engaño, Historia, Intimidación, Perspicacia, Investigación, Naturaleza, Religión, Percepción o Persuasión; además conoces 1 idioma adicional a tu elección, de las tablas de idiomas del Player's Handbook. Simbiosis Sostenida (Sustained Symbiosis): cuando fallas una tirada de salvación, puedes usar tu Reacción y gastar 1 de tus Dados de Golpe: tiras el dado y sumas el resultado a la tirada de salvación, pudiendo convertir el fallo en éxito. Usos = tu bonificador de competencia; recuperas todos los usos gastados al terminar un Descanso Largo. Agenda Simbiótica (Symbiotic Agenda): justo después de hacer una Prueba de d20 y sacar un 1 en el d20, tu simbionte intenta tomar el control: haces una salvación de CAR (CD 13 + tu bonificador de competencia); si fallas, quedas Hechizado durante 1d12 horas. Mientras estés Hechizado, debes intentar seguir las órdenes del simbionte y favorecer sus objetivos, según determine el DM. Cada vez que sufras daño, puedes repetir esta salvación y terminar el efecto si la superas. A criterio del DM, puedes tener que hacer esta salvación siempre que actúes en contra de la agenda del simbionte." },
  { n:"Touch of Death [THW 2024]", tipo:"Dark Gift (THW 2024)", a:"A", d:"Req. Campaña Ravenloft. Toque de la Muerte (Death Touch): aprendes el truco Chill Touch y puedes lanzarlo sin componentes. El daño necrótico que infliges con este conjuro ignora la Resistencia. Tu característica de lanzamiento para este conjuro es INT, SAB o CAR (a elección al obtener la dote). Atracción de la Tumba (Pull of the Grave): tienes Desventaja en las tiradas de salvación de muerte." },
  { n:"Watchers [THW 2024]", tipo:"Dark Gift (THW 2024)", a:"A", d:"Req. Campaña Ravenloft. Ojos Prestados (Borrowed Eyes): siempre tienes preparados Beast Sense y Speak with Animals. Puedes lanzar cada uno sin espacio de conjuro, pero debes terminar un Descanso Largo antes de volver a lanzarlo así; también puedes lanzarlos con tus espacios de conjuro del nivel apropiado. Tu característica de lanzamiento para estos conjuros es INT, SAB o CAR (a elección al obtener la dote). Sospecha Aguzada (Heightened Suspicion): cada vez que realizas la acción Buscar, puedes tirar 1d4 y sumar el resultado a cualquier Prueba de característica hecha como parte de esa acción. Vigilantes Incesantes (Incessant Watchers): tienes Desventaja en las tiradas de salvación contra el conjuro Scrying. Además, justo después de hacer una Prueba de d20 y sacar un 1 en el d20, la paranoia amenaza con abrumarte: haces una salvación de SAB (CD 13 + tu bonificador de competencia); si fallas, tienes Desventaja en las Pruebas de d20 durante 1 minuto. Puedes repetir la salvación al final de cada uno de tus turnos y terminar el efecto antes si la superas." },
];
